WITH payload AS (SELECT $archive_payload$[{"id":"8af33471-c0f0-5c16-a84d-aa38cb7e7de1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش وحبوب محظورة مجردة عن القصد -إثبات بالشهادة -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد -منع من السفر.","document_number":"3461349","case_number":"33443618","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/14","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش وحبوب محظورة مجردة عن القصد -إثبات بالشهادة -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد -منع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3461349:‬تاريخه‪1434/03/14:‬هـ‬\n                       ‫رقم الدعوى‪33443618:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34819715‬تاريخه‪1434/05/06:‬هـ‬\n\n\n     ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش وحبــوب محظــورة مجــردة عــن‬\n     ‫القصــد‪ -‬إثبــات بالشــهادة‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة‬\n                                                  ‫واإلبعــاد ‪ -‬منــع مــن الســفر‪.‬‬\n\n\n\n\n     ‫املــواد (‪ )39‬والفقــرة (‪ )1،2‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪)62‬‬\n                             ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n     ‫دعــوى جزائيــة عامــة ضــد املدعــى عليهمــا تتضمــن طلــب إثبــات إدانتهمــا‬\n     ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة حيــازة مجــردة ‪ ،‬واحلكــم‬\n     ‫عليهمــا بعقوبــة الســجن واإلبعــاد عــن البــاد لــأول واملنــع مــن الســفر‬\n     ‫للثانــي طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت القبض‬\n     ‫عليهمــا يف إحــدى املــزارع بعــد تفتيشــها والعثــور فيهــا علــى املضبوطات‪،‬‬\n     ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n     ‫املخــدر واإلمفيتامــن‪ ،‬أنكــرا أمــام احملكمــة مــا أســنده إليهمــا‬\n     ‫املدعــي العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت‬\n     ‫ســماع شــهادة شــهود محضــر القبــض فشــهدوا مبــا يثبــت الدعــوى‪،‬‬\n     ‫قضــت احملكمــة بإدانــة املدعــى عليهمــا بجميــع ما نســب إليهمــا وقررت‬\n\n‫‪69‬‬\n\f‫تعزيــر كل واحــد منهمــا بســجنه ملــدة ثــاث ســنوات وجلــده مائتــي جلدة‬\n‫مفرقــة وتغرميــه مبلــغ ثالثــة آالف ريــال وإبعــاد األول عــن البــاد بعــد‬\n‫انتهــاء محكوميتــه ومنــع الثانــي مــن الســفر خــارج اململكــة ملــدة ثــاث‬\n‫ســنوات‪ ،‬قنعــا املدعــى عليهمــا باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n                      ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )331251277‬وتاريــخ ‪1433/7/5‬ه ـ‬\n‫واحملالــة مــن فضيلــة الرئيس برقــم (‪ )33443618‬وتاريــخ ‪1433/7/5‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ‪ ........‬ضــد ‪ ........‬ورفيقــه املتهمــن يف‬\n‫قضيــة حيــازة حبــوب محظــورة وحشــيش عليــه ففــي هــذا اليــوم األربعــاء‬\n‫‪1434/2/20‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة احلاديــة عشــرة‬\n‫وفيهــا حضــر املدعــي العــام املوجــه باخلطــاب رقــم (‪ )9882‬وتاريــخ‬\n‫‪1433/3/22‬ه ـ وادعــى علــى احلاضريــن ‪ ........‬أثيوبــي اجلنســية يحمــل‬\n‫البطاقــة البديلــة رقــم (‪ )........‬يف ‪1433/3/28‬ه ـ الصــادرة مــن حــرس‬\n‫احلــدود قطــاع ‪ ........‬و‪ ........‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم‬\n‫ســجله املدنــي (‪ )........‬أنــه بتاريــخ ‪ 1433/3/28‬ه ـ وأثنــاء قيــام أفــراد‬\n‫حــرس احلــدود بواجبهــم يف املوقــع املســمى ‪ ........‬وردت معلومــات تفيــد‬\n‫أن هنــاك أشــخاصا يقومــون ببيــع املخــدرات وباالجتــاه إلــى املوقــع داخــل‬\n‫إحــدى املــزارع مت تطويقهــا ومبداهمتهــا مت القبــض علــى املدعــى عليهمــا‬\n‫وبتفتيــش املوقــع ضبطــت (‪ )29‬تســع وعشــرون حبــة مــن حبــوب‬\n\n                                                                                        ‫‪70‬‬\n\f     ‫الكبتاجــون املنبهــة ومــا وزنــه (‪ )35‬خمســة وثالثــون جرامــا مــن مــادة‬\n     ‫احلشــيش املخــدر و(‪ )55‬خمــس وخمســون قــارورة عــرق (مت فــرز أوراق‬\n     ‫مســتقلة لهــا) وبندقيــة شــميزر ومسدســات متنوعــه وعــدد مــن املخــازن‬\n     ‫والطلقــات (مت فــرز أوراق مســتقلة لهــا) وأثبــت التقريــران الكيميائيــان‬\n     ‫الشــرعيان رقــم (‪ )6337‬لعــام ‪1433‬ه ـ ورقــم (‪ 8951‬س‪ )2‬لعــام ‪1433‬هـ‬\n     ‫الصــادران مــن مركــز الســموم والكيميــاء الشــرعية مبنطقــة مكــة‬\n     ‫املكرمــة إيجابيتهــا حلبــوب اإلمفيتامــن املنبهــة احملظــورة املدرجــة‬\n     ‫ضمــن اجلــدول رقــم (‪ )2‬فئــة (ب) وإيجابيــة العينــة املرســلة مــن الكميــة‬\n     ‫املضبوطــة ملــادة احلشــيش املخــدر واحتوائهــا علــى املــادة الفعالــة لــه‬\n     ‫واملــدرج ضمــن اجلــدول رقــم (‪ )1‬فئــة (أ) مــن نظــام املخــدرات واملؤثــرات‬\n     ‫العقليــة والصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ‬\n     ‫وباســتجواب املدعــى عليهمــا ومواجهتهمــا بالتهمــة املنســوبة إليهمــا‬\n     ‫أنكــرا حيازتهمــا للكميــة املضبوطــة مــن مــادة احلشــيش املخــدر‬\n     ‫وحبــوب الكبتاجــون املنبهــة وبالبحــث عــن ســوابقهما عثــر للمدعــى‬\n     ‫عليــه األول علــى ســابقة واحــدة وهــي تهريــب اخلمــور وعثــر للمدعــى‬\n     ‫عليــه الثانــي علــى ســابقة واحــدة وهــي حيــازة املخــدرات واســتعمال‬\n     ‫املخــدرات وترويــج املخــدرات وقــد أســفر التحقيــق مــع املدعــى عليهمــا‬\n     ‫عــن توجيــه االتهــام إليهمــا بحيــازة كميتــي احلبــوب احملظــورة واحلشــيش‬\n     ‫املخــدر املذكورتــن أعــاه حيــازة مجــرده وألن مــا أقــدم عليــه املدعــى‬\n     ‫عليهمــا املذكــوران فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا فقــد طلــب‬\n     ‫املدعــي العــام إثبــات إدانتهمــا مبــا أســند إليهمــا واحلكــم بتعزيرهمــا‬\n     ‫شــرع ًا يف ضــوء املــادة (‪ )39‬مــن نظــام مكافحــة املخــدرات الصــادر‬\n     ‫باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ واحلكــم مبنــع‬\n\n\n‫‪71‬‬\n\f‫املدعــى عليــه الثانــي مــن الســفر خــارج البــاد بعــد انقضــاء محكومتيــه‬\n‫اســتنادا للفقــرة األولــى مــن املــادة (‪ )56‬مــن ذات النظــام واحلكــم بإبعــاد‬\n‫املدعــى عليــه األول عــن البــاد اســتنادا للفقــرة الثانيــة مــن املــادة (‪)56‬‬\n‫مــن ذات النظــام وبعــرض الدعــوى علــى املدعــى عليــه األول عــن طريــق‬\n‫املترجــم ‪ ........‬أثيوبــي اجلنســية يحمــل رخصة اإلقامــة رقم ‪ ........‬الصادرة‬\n‫مــن جيــزان صــدق واقعــة القبــض وزمانهــا ومكانهــا ونفــى علمــه‬\n‫وعالقتــه مبــا مت ضبطــه وقــرر أنــه عامــل يف املزرعــة املشــار إليها هكذا‬\n‫أجــاب وصــدق الســابقة املســجلة عليــه وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه الثانــي صــدق واقعــة القبــض وزمانهــا ومكانهــا ونفــى علمــه‬\n‫وعالقتــه مبــا مت ضبطــه وقــرر أن املزرعــة ملــك لــه ورثهــا مــن أبيــه وفيهــا‬\n‫منــزل عائــد إليــه هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى‬\n‫ال مــن ‪ ........‬ســعودي اجلنســية يحمــل الهويــة‬  ‫الدعــوى أحضــر للشــهادة ك ً‬\n‫الوطنيــة ورقــم ســجله املدنــي ‪ ........‬واحلفيظــة رقــم ‪ ........‬وتاريــخ‬\n‫‪1409/9/24‬ه ـ الصــادرة مــن أحــوال جــازان ‪ ........‬ســعودي اجلنســية‬\n‫يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي‪ ........‬واحلفيظــة رقــم‪........‬‬\n‫وتاريــخ ‪1414/11/21‬ه ـ الصــادرة مــن أحــوال صبيــا وبســؤال األول عما‬\n‫ا أشــهد بــاهلل تعالــى أنــه يف يــوم مــا قبــل ســنة تقريب ـ ًا‬\n                                                                  ‫لديــه أجــاب قائ ـ ً‬\n‫وردت إلينــا معلومــات تفيــد أن موقعــا يســمى ‪ ........‬يتبــع محافظــة ‪........‬‬\n‫اتخــذ لترويــج املخــدرات مــن قبــل أشــخاص مــن اجلنســيات األفريقيــة‬\n‫وقــد توجهــت بســيارة مدنيــة ضمــن الفرقــة وباملراقبــة شــاهدة ســيارات‬\n‫وأناسـ ًا يتــواردون علــى املوقــع ويخرجــون منــه واملوقــع عبــارة عــن مزرعــة‬\n‫ومبداهمــة املوقــع كان املدعــى عليــه جالس ـ ًا علــى بســاط وحولــه‬\n‫مجموعــة أشــخاص ووجدنــا علــى البســاط (بكــت) دخــان بــه قطعــة‬\n\n\n                                                                                          ‫‪72‬‬\n\f     ‫حشــيش كانــت أمــام املدعــى عليــه ‪ ........‬إلــى مســافة متــر ونصــف املتــر‬\n     ‫أمــا املدعــى عليــه األثيوبــي فقــد حــاول الهــرب لكنــه مت القبــض عليــه‬\n     ‫وكان داخــل بيــت مــن القــش وعنــد القبــض عليــه دلنــا علــى كميــات‬\n     ‫مــن املســكر مــن نــوع العــرق وبتفتيــش األشــخاص الذيــن كانــوا‬\n     ‫جالســن مــع املدعــى عليــه لــم جنــد معهــم شــيئ ًا وبتفتيــش املوقــع وهــو‬\n     ‫عبــارة عــن غرفــة وبيــت مــن القــش ضبطنــا يف الغرفــة كميــة مــن احلبوب‬\n     ‫احملظــورة وبعــض األســلحة وبعــد مغــادرة املوقــع تركنــا أحــد الزمــاء‬\n     ‫بزيــه املدنــي فجــاء بعــض األشــخاص إليــه وطلبوا شــراء حبوب وحشــيش‬\n     ‫واســتعدوا بدفــع مبالــغ ماليــة هــذا مــا لــدي وبــه أشــهد وبســؤال الثانــي‬\n     ‫ا أشــهد بــاهلل تعالــى أنــه يف يــوم مــا قبــل‬ ‫منهمــا عمــا لديــه أجــاب قائ ـ ً‬\n     ‫ســنة تقريب ـ ًا وردت إلينــا معلومــات تفيــد أن موقعــا يســمى ‪ ........‬يتبــع‬\n     ‫محافظــة ‪ ........‬اتخــذ لترويــج املخــدرات من قبل أشــخاص من اجلنســيات‬\n     ‫األفريقيــة وقــد توجهــت بســيارة مدنيــة ضمــن الفرقــة وباملراقبــة شــاهدة‬\n     ‫ســيارات وأناس ـ ًا يتــواردون علــى املوقــع ويخرجــون منــه واملوقــع عبــارة‬\n     ‫عــن مزرعــة ومبداهمــة املوقــع كان املدعــى عليــه جالس ـ ًا علــى بســاط‬\n     ‫وحولــه مجموعــة أشــخاص ووجدنــا علــى البســاط (بكــت) دخــان بــه‬\n     ‫قطعــة حشــيش كانــت أمــام املدعــى عليــه ‪ ........‬إلــى مســافة متر ونصف‬\n     ‫املتــر أمــا املدعــى عليــه األثيوبــي فقــد حــاول الهــرب لكنــه مت القبــض‬\n     ‫عليــه وكان داخــل بيــت مــن القــش وعنــد القبــض عليــه دلنــا علــى‬\n     ‫كميــات مــن املســكر مــن نــوع العــرق وبتفتيــش األشــخاص الذيــن‬\n     ‫كانــوا جالســن مــع املدعــى عليــه لــم جنــد معهــم شــيئ ًا وبتفتيــش املوقــع‬\n     ‫وهــو عبــارة عــن غرفــة وبيــت مــن القــش ضبطنــا يف الغرفــة كميــة مــن‬\n     ‫احلبــوب احملظــورة وبعــض األســلحة وبعــد مغــادرة املوقــع تركنــا أحــد‬\n\n\n‫‪73‬‬\n\f‫الزمــاء بزيــه املدنــي فجــاء بعــض األشــخاص إليــه وطلبــوا شــراء حبــوب‬\n‫وحشــيش واســتعدوا بدفــع مبالــغ ماليــة هــذا مــا لــدي وبــه أشــهد وبعرض‬\n‫الشــاهدين وشــهادتهما على املدعى عليه األول نطق بالعربية ركيكة‬\n‫حســب نطقــه وأنكــر داللتــه للفرقــة القابضــة عــن موقــع املســكر ونفى‬\n‫علمــه وعالقتــه مبــا ضبطــه ولم يطعن يف الشــاهدين وبعرض الشــاهدين‬\n‫وشــهادتهما علــى املدعــى عليــه الثانــي نفــى علمه وعالقتــه مبا مت ضبطه‬\n‫وأنكــر ضبــط كميــة احلشــيش أمامــه ولــم يطعــن يف الشــاهدين وقــرر‬\n‫أن األشــخاص الذيــن كانــوا يتــواردون علــى مزرعتــه هــم مــن قرابتــه‬\n‫ويأتــون للحديــث معــه هكــذا أجــاب ويف اجللســة حضــر كل مــن ‪........‬‬\n‫ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي‪ ........‬و‬\n‫‪ ........‬ســعودي اجلنســية يحمــل الهويــة الوطنيــة ورقــم ســجله املدنــي‪........‬‬\n‫وشــهدا بعدالــة الشــاهدين وأنهمــا مقبــوال الشــهادة وبالرجــوع إلــى أوراق‬\n‫املعاملــة جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق علــى‬\n‫اللفــة رقــم (‪ )43‬والتقريــر اآلخــر املرفــق علــى اللفــة رقــم (‪ )67‬كمــا‬\n‫جــرى االطــاع علــى ثبــت ســوابق املدعــى عليهمــا فوجــدت مطابقــة ملــا‬\n‫جــاء يف الدعــوى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإلقــرار املدعــى عليــه األول بأنــه يعمــل يف املزرعــة املذكورة يف الدعوى‬\n‫وإلقــرار املدعــى عليــه الثانــي بــأن املزرعــة ملــك لــه وكــذا مــا فيهــا مــن‬\n‫بنــاء وإلنكارهمــا عائديــة كميتــي احلبــوب احملظــورة واحلشــيش املخدر‬\n‫إليهمــا فقــد قــررت مــا يلــي أوال ثبتــت لــدي إدانــة املدعــى عليــه األول‬\n‫باالشــتراك يف حيــازة كميتــي احلبــوب احملظــورة واحلشــيش املخــدر‬\n‫املشــار إليهمــا يف الدعــوى دون أن يســفر عــن قصــده مــن ذلــك وهــو جــرم‬\n‫يســتحق العقوبــة عليــه يف ضــوء املــادة (‪ )39‬مــن نظــام مكافحــة‬\n\n\n                                                                                        ‫‪74‬‬\n\f     ‫املخــدرات وملــا شــهد بــه الشــهود املعدلــون شــرعا مــن رؤيتهــم ألنــاس‬\n     ‫يتــواردون علــى املوقــع ويخرجــون منــه قبــل حادثة القبــض ومجيء آخرين‬\n     ‫بعــد القبــض لطلــب شــراء املخــدرات مــن رجــل األمــن الــذي بقــي يف‬\n     ‫املوقــع بلباســه املدنــي كل ذلــك يوجــه إليــه الشــبهة بالترويــج واســتنادا‬\n     ‫إلــى املــادة (‪ )1/62‬مــن ذات النظــام فقــد حكمــت عليــه بالســجن مــدة‬\n     ‫ثــاث ســنوات اعتبــارا مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه‬\n     ‫القضيــة يف ‪1433/3/28‬ه ـ وجلــده مائتــي جلــدة علــى دفعــات كل دفعة‬\n     ‫خمســون جلــدة وبــن كل دفعــة والتــي تليهــا شــهر وتغرميــه مبلغــا قــدره‬\n     ‫ثالثــة آالف ريــال يــؤول إلــى خزينــة الدولــة العامــة كما حكمــت بإبعاده‬\n     ‫عــن البــاد بعــد انتهــاء محكوميتــه بالســجن اســتنادا للمــادة (‪)2/56‬‬\n     ‫مــن النظــام املشــار إليــه ثانيــا ثبتــت لــدي إدانــة املدعــى عليــه الثانــي‬\n     ‫باالشــتراك يف حيــازة كميتــي احلبــوب احملظــورة واحلشــيش املخــدر‬\n     ‫املشــار إليهمــا يف الدعــوى دون أن يســفر عــن قصــده مــن ذلــك وهــو جــرم‬\n     ‫يســتحق العقوبــة عليــه يف ضــوء املــادة (‪ )39‬مــن نظــام مكافحــة‬\n     ‫املخــدرات وملــا شــهد بــه الشــهود املعدلــون شــرعا مــن رؤيتهــم ألنــاس‬\n     ‫يتــواردون علــى املوقــع ويخرجــون منــه قبــل حادثة القبــض ومجيء آخرين‬\n     ‫بعــد القبــض لطلــب شــراء املخــدرات مــن رجــل األمــن الــذي بقــي يف‬\n     ‫املوقــع بلباســه املدنــي كل ذلــك يوجــه إليــه الشــبهة بالترويــج واســتنادا‬\n     ‫إلــى املــادة (‪ )1/62‬مــن ذات النظــام فقــد حكمــت عليــه بالســجن مــدة‬\n     ‫ثــاث ســنوات اعتبــارا مــن تاريــخ القبــض عليــه وإيقافــه علــى ذمــة هــذه‬\n     ‫القضيــة يف ‪1433/3/28‬ه ـ وجلــده مائتــي جلــدة علــى دفعــات كل دفعة‬\n     ‫خمســون جلــدة وبــن كل دفعــة والتــي تليهــا شــهر وتغرميــه مبلغــا قــدره‬\n     ‫ثالثــة آالف ريــال يــؤول إلــى خزينــة الدولــة العامــة كمــا حكمــت مبنعــه‬\n\n\n‫‪75‬‬\n\f‫مــن الســفر خــارج البــاد مــدة ثــاث ســنوات بعــد انتهــاء محكوميتــه‬\n‫بالســجن اســتنادا للمــادة (‪ )1/56‬مــن النظــام املشــار إليــه هــذا مــا ثبــت‬\n‫لــدي وبــه حكمــت وبعرضــه علــى أطــراف الدعــوى قــرر املدعــي العــام‬\n‫معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك‬\n‫وقــرر املدعــى عليهمــا القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة‬\n‫العاشــرة إال ربعــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                               ‫وآله وصحبه أجمعني حرر يف ‪1434/3/11‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة االولــى‬\n‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n‫‪ 3465004‬وتاريــخ ‪1434/3/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ......../‬برقــم ‪ 3461349‬وتاريــخ‬\n‫‪1434/03/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد كل مــن ‪........ /‬‬\n‫ســعودي اجلنســية و‪ ..............‬أثيوبــي اجلنســية يف قضيــة (مخــدرات)‬\n‫علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪76‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":69,"source_page_end":76,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3232876d868c7c595331e3ca5ebea38cc18fa4c54ab2c41913a11fce7c1c3072","normalized_text_hash":"3e5422089ca6e6b29a68ea1c9257e00d1c86b3755c1b071c72d442c4afbf0561","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p69-3461349"},{"id":"7e3688e8-3436-59c1-8f39-01bdd0011f21","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي والترويج -شروع يف الترويج - حد املسكر -تعزير بالسجن واجللد واإلبعاد والغرامة واملصادرة.","document_number":"3420010","case_number":"33447030","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/24","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي والترويج -شروع يف الترويج - حد املسكر -تعزير بالسجن واجللد واإلبعاد والغرامة واملصادرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 3420010 :‬تاريخه ‪1434/1/24 :‬هـ‬\n                      ‫رقم الدعوى ‪33447030 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 341252596‬تاريخه‪1434/07/09:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي والترويــج ‪ -‬شــروع يف الترويــج ‪-‬‬\n     ‫حــد املســكر ‪ -‬تعزيــر بالســجن واجللــد واإلبعــاد والغرامــة واملصــادرة‪.‬‬\n\n\n\n\n     ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( كل مســكر خمــر وكل خمــر حــرام)‬\n                                                                   ‫رواه مســلم ‪.‬‬\n     ‫‪ -2‬املــواد ( ‪ ) 56 - 53 - 41 - 38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــي العــام ضــد ثالثــة أشــخاص أحدهــم مقيــم وذلــك بتوجيــه‬\n     ‫االتهــام ضــد املقيــم بحيــازة كميــة مــن احلشــيش املخــدر بقصــد الترويــج‬\n     ‫والشــروع يف ترويجــه وتعاطيــه الســابق لــه‪ ،‬واتهــام الثانــي والثالــث‬\n     ‫باالشــتراك يف حيــازة الكميــة املضبوطــة بقصــد الترويــج عــن طريــق‬\n     ‫املســاعدة والشــروع يف ترويجهــا واشــتراكهم يف حيــازة مشــرط‬\n     ‫ومقــص عليهمــا آثــار ملــادة احلشــيش املخــدر بقصــد الترويــج‪ ،‬وطلــب‬\n     ‫املدعــي العــام إثبــات مــا أســند إليهــم واحلكــم عليهــم بالســجن واجللــد‬\n     ‫والغرامــة ومصــادرة جــوال األول وإلغــاء شــريحته وعــدم صرفهــا مــرة‬\n     ‫أخــرى وإبعــاد املدعــى عليــه املقيــم عــن اململكــة ومنــع املدعــى عليــه‬\n\n‫‪77‬‬\n\f‫الثانــي مــن الســفر بعــد انتهــاء عقوبتــه‪ ،‬مت القبــض علــى املدعــى عليهــم‬\n‫بعــد إخباريــة مفادهــا أن املدعــى عليــه املقيــم يــروج احلشــيش املخــدر‬\n‫واســتعد املصــدر لإليقــاع بــه ومت االتفــاق علــى املوقــع احملــدد وحضــر‬\n‫املصــدر مــع أحــد أفــراد الفرقــة القابضــة وتقابــل املصــدر مــع املدعــى‬\n‫عليــه املقيــم وأعطــى املصــدر اإلشــارة بعــد اســتالم الكميــة املتفــق‬\n‫عليهــا وقبــض علــى املدعــى عليــه املقيــم وكان يرافقــه املدعــى عليــه‬\n‫الثانــي والثالــث يف هــذه املهمــة‪ ،‬إقــرار املدعــى عليــه املقيــم مبــا نســب‬\n‫إليــه‪ ،‬إنــكار املدعــى عليهمــا الثانــي والثالــث للدعــوى‪ ،‬إحضار املدعي‬\n‫العــام لبينــة غيــر موصلــة تثبــت إدانــة املدعــى عليهمــا الثانــي والثالــث‬\n‫ولكنهــا توجــه الشــبهة ضدهمــا‪ ،‬توجيــه الشــبهة بحــق املدعــي عليهمــا‬\n‫الثانــي والثالث‪،‬إقامــة حــد املســكر علــى املدعــى عليــه املقيــم وتعزيــره‬\n‫بالســجن واجللــد والغرامــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة وبيعــه‬\n‫وإيــداع ثمنــه يف بيــت مــال املســلمني لصرفــه يف أوجــه البــر وإبعــاده خــارج‬\n‫البــاد‪ ،‬وتعزيــر املدعــى عليهمــا الثانــي والثالــث بالســجن واجللــد‪ ،‬ثــم‬\n                                ‫تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنا‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33447030‬‬\n‫وتاريخ ‪ 1433/07/06‬هـ املقيدة باحملكمة برقم ‪ 331252713‬وتاريخ‬\n‫‪ 1433/07/05‬ه ـ ففــي يــوم الســبت املوافــق‪ 1433/08/24‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــر املدعــي العــام ‪..........‬ســعودي‬\n\n                                                                                      ‫‪78‬‬\n\f     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬املكلــف مبوجــب اخلطــاب‬\n     ‫ال بصفتي مدعي ًا عام ًا بدائرة‬        ‫رقم ‪..........‬يف ‪1432/1/16‬هـ وادعى قائ ً‬\n     ‫االدعاء العام مبحافظة جدة أدعي على كل من‪ )24( ،.......... :‬عاماً‪،‬‬\n     ‫‪ ........‬فلسطيني اجلنسية ‪ ،‬مبوجب رخصة اإلقامة رقم (‪ ،)..........‬املهنة‬\n     ‫‪ /‬طالــب ‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد‬\n     ‫التوقيــف رقــم (ه ـ م‪ )32088/5/2‬وتاريــخ ‪1433/5/11‬هــ‪،.......... .‬‬\n     ‫(‪ )26‬عامـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقــم (‪، )..........‬‬\n     ‫املهنــة ‪ /‬طالــب ‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر‬\n     ‫متديــد التوقيــف رقــم (‪ )..........‬وتاريــخ ‪1433/5/11‬هــ‪)30( ، .......... .‬‬\n     ‫عامـ ًا ‪ ........ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقــم (‪،)..........‬‬\n     ‫املهنــة ‪ /‬طالــب ‪ ،‬موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر‬\n     ‫متديــد التوقيــف رقــم (‪ )..........‬وتاريــخ ‪1433/5/11‬ه ـ املقبــوض عليهــم‬\n     ‫بتاريــخ ‪1433/5/7‬هــ‪ .‬باالطــاع علــى محضــر االنتقــال والضبــط‬\n     ‫والتفتيــش رقــم (بــدون) املرفــق واملعــد مــن قبــل مكافحــة املخــدرات‬\n     ‫ـاء علــى معلومــات‬   ‫مبحافظــة جــدة بتاريــخ ‪1433/5/7‬ه ـ املتضمــن أنــه بنـ ً‬\n     ‫مــن املدعــى عليــه ‪ ،.......... /‬واملوقــوف علــى ذمــة القضيــة رقــم (‪)..........‬‬\n     ‫مفادهــا وجــود شــخص فلســطيني اجلنســية يدعــى ‪ ،..........‬يتوســط يف‬\n     ‫بيــع مــادة احلشــيش املخــدر ويتواجــد علــى جــوال رقــم (‪ )..........‬وأنــه‬\n     ‫عندمــا يحضــر الكميــة املتفــق عليهــا يحضــر مصدرهــا معــه ‪ ،‬عليــه‬\n     ‫جــرى اإليعــاز للمصــدر املدعــى عليــه باالتصــال علــى املعنــي باإلخباريــة‬\n     ‫لالتفــاق علــى شــراء الكميــة املناســبة وعلــى مســمع مــن الفرقــة اتصــل‬\n     ‫املصــدر ورد عليــه املعنــي وطلــب منــه شــراء كيلــو فطلــب منــه املعنــي‬\n     ‫االنتظــار وقــال لــه بعبــارة (أشــوف الرجــال وأكلمــك) ‪ ،‬ويف متام الســاعة‬\n\n\n‫‪79‬‬\n\f‫ـاء اتصــل باملصــدر وســأله عــن الفائــدة التــي ســتعود‬   ‫احلاديــة عشــر مسـ ً‬\n‫عليــه مــن هــذه البيعــة وســأله املصــدر عــن ســعر الكيلــو فقــال بأربعــة‬\n‫عشــر ألــف فقــال املعنــي أنــا آخــذ خمســمائة وأنــت خمســمائة ونحســب‬\n‫الكيلــو علــى املشــتري بخمســة عشــر ألــف فطلــب املعنــي مــن املصــدر‬\n‫أن يقابلــه بجــوار مستشــفى ‪ ..........‬وانتهــى االتصــال‪ ،‬وبســؤال املصــدر‬\n‫املدعــى عليــه عــن إمكانيــة مرافقتــه مــن قبــل أحــد أفــراد الفرقــة‬\n‫فذكــر أن ذلــك ممكــن فتــم تكليــف أحــد أفــرد الفرقــة لتمثيــل دور‬\n‫املشــتري وتأمــن مبلــغ الشــراء وترقيــم جــزء منــه ‪ ،‬وباالنتقــال للموقــع‬\n‫املتفــق عليــه مت التمركــز باملوقــع حتــى الســاعة احلاديــة عشــر والنصــف‬\n‫ـاء وبعــد عــدة اتصــاالت طلــب املدعــى عليــه األول تغييــر املوقــع ملوقــع‬\n                                                                             ‫مسـ ً‬\n‫آخــر بجــوار أحــد املتاجــر بحــي ‪ ..........‬فتــم االنتقــال ويف متــام الســاعة‬\n‫الثانيــة عشــر والربــع تقريب ـ ًا وأثنــاء االنتظــار باملوقــع أشــار املصــدر‬\n‫املدعــى عليــه لشــخص كان يركــب يف املقعــد اخللفــي للســيارة مــن‬\n‫نــوع ‪ ........‬حتمــل لوحــة رقــم (‪ )..........‬اتضــح أنــه األول والــذي ورد منــه‬\n‫اتصــال وطلــب مــن املصــدر املدعــى عليــه الســير خلفــه فتــم التحــرك‬\n‫وعنــد التوقــف بجــوار الســيارة رفــع األول يــده وبهــا الكميــة املتفق عليها‬\n‫وقــد أعطيــت اإلشــارة للقبــض عليهــم فتمــت محاصــرة الســيارة وحــاول‬\n‫قائدهــا الهــرب بالرجــوع للخلــف إال أنــه متــت الســيطرة والقبــض عليهــم‬\n‫فــاألول كان يجلــس يف املقعــد اخللفــي للســيارة‪ ،‬والثانــي كان يجلــس‬\n‫يف املقعــد األمامــي بجــوار الســائق‪ ،‬والثالــث قائــد الســيارة وبتفتيشــهم‬\n‫جميعـ ًا لــم يعثــر معهــم علــى شــيء مــن املمنوعــات وضبطــت قطعــة ســوداء‬\n‫اللــون تــزن (‪ )1001.5‬جــرام يشــتبه أن تكــون احلشــيش املخــدر بــن‬\n‫فخــذي املدعــى عليــه األول‪ ،‬وبتفتيــش الســيارة ضبــط بالــدرج علــى‬\n\n\n                                                                                       ‫‪80‬‬\n\f     ‫أدوات تقطيــع مــادة احلشــيش املخــدر وهــي عبــارة عــن مشــرط ومقــص‬\n     ‫بهــا آثــار يشــتبه أن تكــون مــادة احلشــيش املخــدر وأثبــت التقريــر‬\n     ‫الكيميائــي رقــم (‪ )..........‬لعــام ‪1433‬ه ـ إيجابيــة العينتــن (أ‪،‬ب) مــن‬\n     ‫املــادة املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر واحتوائهــا‬\n     ‫علــى املــادة الفعالــة لــه واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n                                          ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n     ‫وباســتجواب املدعــى عليــه األول‪.......... /‬أقــر بحيــازة مــا بلــغ وزنــه‬\n     ‫(‪ )1001.5‬جــم مــن مــادة احلشــيش املخــدر وأن قصــده مــن حيازتهــا‬\n     ‫أخــذ الفائــدة والكســب املــادي وأفــاد بتعاطيــه للحشــيش املخــدر‬\n     ‫منــذ أســبوعني تقريب ـ ًا ‪ ،‬وأقــر بدايــة بأنــه حصــل علــى الكميــة مــن‬\n     ‫املدعــى عليــه الثانــي ثــم رجــع عــن أقوالــه وأفــاد بأنــه حصــل عليهــا مــن‬\n     ‫شــخص صومالــي اجلنســية ال يعرفــه يســكن بحــي ‪..........‬مببلــغ تســعة‬\n     ‫آالف ريــال‪ .‬باســتجواب املدعــى عليــه الثانــي ‪ /.......... /‬أنكــر مــا نســب‬\n     ‫ا وأفــاد بأنــه يف يــوم اجلمعــة املوافقــة ‪1433/5/7‬ه ـ‬    ‫إليــه جملــة وتفصيـ ً‬\n     ‫ـاء كان برفقــة الثالــث يف‬    ‫ويف متــام الســاعة احلاديــة عشــر والنصــف مسـ ً‬\n     ‫ســيارته وكانــا ينويــان تنــاول طعــام العشــاء وأثنــاء حتركهمــا شــاهد‬\n     ‫األول يســير علــى قدميــه يف الشــارع العــام فاتصــل عليــه وســأله بعبــارة‬\n     ‫(ويــن رايــح) فـ ّـرد عليــه بعبــارة (ابغــاك توصلنــي قريــب مــن احلــارة ملقابلــة‬\n     ‫صاحبــي) فركــب األول معهمــا وأثنــاء وصولهــم مت القبــض عليهــم ‪.‬‬\n     ‫باســتجواب املدعــى عليــه الثالــث‪.......... /‬أنكــر مــا نســب إليــه جملــة‬\n     ‫ا وأنكــر عالقتــه مبــا مت ضبطــه داخــل درج الســيارة ونفــى‬             ‫وتفصي ـ ً‬\n     ‫تعاطيــه ألي نــوع مــن أنــواع املخــدرات‪ .‬وانتهــى التحقيــق بتوجيــه االتهــام‬\n     ‫إلــى املدعــى عليــه ‪ ،..........‬بحيــازة مــا بلــغ وزنــه (‪ )1001.5‬ألــف وواحــد‬\n\n\n‫‪81‬‬\n\f‫جرام ـ ًا وخمســة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر بقصــد‬\n‫الترويــج والشــروع يف ترويجهــا وتعاطيــه لنوعهــا مــن الســابق ‪ ،‬واتهــام‬\n‫الثانــي‪ ،.......... /‬والثالــث‪ ،.......... /‬باالشــتراك يف حيــازة الكميــة‬\n‫املضبوطــة بقصــد الترويــج عــن طريــق املســاعدة والشــروع يف ترويجهــا‬\n‫واشــتراكهم يف حيــازة مشــرط ومقــص عليهمــا آثــار ملــادة احلشــيش‬\n‫املخــدر بقصــد الترويــج ‪ ،‬اســتناد ًا للفقــرة (‪ )2‬مــن املــادة الثالثــة مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وذلــك لألدلــة والقرائــن‬\n‫املرصــودة مبلــف القضيــة‪ .‬وباالطــاع علــى ســوابقهما لــم يعثــر لهــم‬\n‫علــى ســوابق مســجلة عليهــم‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليهــم‬\n‫املذكوريــن وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا مــن األفعــال احملرمــة‬\n‫شــرع ًا واملجرمــة نظام ـ ًا طبقــا للمــادة الثالثــة مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪39/‬‬\n‫وتاريــخ ‪1426/7/8‬هــ‪ ،‬واملعاقــب عليهــا اســتناد ًا للمادتــن (‪ )41،38‬مــع‬\n‫مراعــاة مــا ورد باملــادة (‪ )62‬مــن ذات النظــام بالنســبة للمدعــى عليــه‬\n‫األول‪ ،‬لــذا أطلــب مــن احملكمــة اجلزئيــة مبحافظــة جــدة إثبــات إدانتهــم‬\n‫مبــا أســند إليهــم ومعاقبهــم بالعقوبــات األصليــة والتكميليــة التاليــة‪:‬‬\n‫أوال بالســجن واجللــد والغرامــة لقــاء مــا أســند إليهــم اســتناد ًا للفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليــه‪ .‬ثانيــا مصــادرة جهــاز الهاتــف اجلــوال العائــد لــأول مــن نــوع‬\n‫(‪ )......‬ذي الرقــم املصنعــي (‪ )..........‬املســتخدم يف ارتــكاب اجلرميــة‬\n‫اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه وإلغــاء اخلدمــة عــن الشــريحة رقــم (‪..........‬وعــدم صرفهــا‬\n‫ملــن أســاء اســتخدامها اســتناد ًا لتعميــم صاحــب الســمو امللكــي وزيــر‬\n\n\n                                                                                        ‫‪82‬‬\n\f     ‫الداخليــة رقــم (‪ )9798‬يف ‪9‬ــ‪1428/2/10‬هــ‪ .‬ثالثـ ًا منــع الثانــي والثالــث‬\n     ‫مــن الســفر خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا وإبعــاد‬\n     ‫األول خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه وعــدم الســماح‬\n     ‫لــه بالعــودة إليهــا ومنعــه مــن دخولهــا وفق ـ ًا للفقرتــن (‪ )1،2‬مــن املــادة‬\n     ‫(‪ )56‬مــن نظــام املخــدرات املشــار إليــه هكــذا ادعــى‪ .‬وبتــاوة الدعــوى‬\n     ‫ا مــا ذكــره‬  ‫علــى املدعــى عليهــم أجــاب املدعــى عليــه األول ‪..........‬قائـ ً‬\n     ‫املدعــي العــام يف دعــواه كلــه صحيــح وأنــا أتعاطــى احلشــيش املخــدر مــن‬\n     ‫قبــل ومــا كان معــي كان بقصــد االجتــار والترويــج وأنــا شــاب أدرس‬\n     ‫يف اجلامعــة ولــم أجتــاوز اخلمســة وعشــرين عامـ ًا مــن عمــري ونــادم علــى‬\n     ‫مــا فعلــت وتائــب إلــى اهلل وليــس علــي ســوابق هكــذا أجــاب وأجــاب‬\n     ‫املدعــى عليــه الثانــي ‪..........‬والثالــث ‪..........‬كل واحــد منهمــا بانفــراد‬\n     ‫ا مــا ذكــره املدعــي العــام غيــر صحيــح فلــم نشــترك مــع املدعــى‬           ‫قائ ـ ً‬\n     ‫عليــه األول ‪..........‬يف الترويــج وليــس لنــا عالقــة مبــا كان معــه وليــس‬\n     ‫لنــا علــم مبــا كان معــه يف الســيارة ومــا كان بالســيارة مشــرط ومقــص‬\n     ‫ا وليــس علينــا ســوابق وال‬    ‫فــا نعلــم عنــه شــيء والســيارة ليســت لنــا أصـ ً‬\n     ‫نتعاطــى املخــدرات هكــذا أجابــا وبســؤال املدعــي العــام ألديــك بينــة‬\n     ‫علــى دعــواك قــال نعــم وأطلــب املهلــة إلحضارهــا ورفعــت اجللســة حلــن‬\n                                                        ‫إحضــار املدعــي العــام البينــة‪.‬‬\n     ‫ويف جلســة أخــرى افتتحــت اجللســه الســاعه ‪ 10‬وحضــر فيهــا املدعــي‬\n     ‫العــام ولــم يحضــر املدعــي عليهــم وبســؤال املدعــي العــام هــل أحضــرت‬\n     ‫البينــة قــال نعــم وهــي كال مــن ‪ ..........‬ســعودي مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪..........‬ويعمــل عســكري برتبــة جنــدي ويبلــغ مــن العمــر ‪ 33‬ســنه‬\n     ‫وليــس بينــه وبــن املدعــي عليهــم أي عــداوة او قرابــه و‪..........‬ســعودي‬\n\n\n‫‪83‬‬\n\f‫مبوجــب الســجل املدنــي رقــم ‪..........‬ويعمــل عســكري برتبــه جنــدي اول‬\n‫ويبلــغ مــن العمــر ‪ 24‬ســنه وليــس بينــه وبــن املدعــى عليهــم أي عــداوة‬\n‫او قرابــه وبســؤالهما عمــا لديهمــا مــن شــهادة اجــاب كل واحــد منهمــا‬\n‫منفــردا قائــا اشــهد هلل بانــي لــم اشــاهد املدعــي عليهمــا الثانــي ‪..........‬‬\n‫والثالــث ‪..........‬يشــتركون يف عمليــة الترويــج ولكــن كانــوا مــع‬\n‫املدعــي عليــه االول ‪..........‬يف ســيارته عندمــا قبضنــا عليهــم الن التنســيق‬\n‫واملتابعــة كان املقصــود فيهــا املدعــي عليــه االول ‪..........‬هــذا مــا لــدي‬\n‫مــن شــهادة واهلل علــى مــا أقــول شــهيد هكــذا شــهد كل واحــد منهمــا‬\n‫ورفعــت اجللســة ويف جلســة أخــرى حضــر فيهــا املدعــي العــام واملدعــى‬\n‫عليهــم وبعــرض شــهادة الشــهود علــى املدعــى عليهمــا الثانــي والثالــث‬\n‫ا ماجــاء يف شــهادة‬      ‫أجــاب قائــا كل واحــد منهمــا علــى انفــراد قائ ـ ً‬\n‫الشــهود صحيــح وليــس لنــا عالقــة بعمليــة الترويــج وكل مــايف األمــر‬\n‫أننــا كنــا مــع املدعــى عليــه األول ‪..........‬أثنــاء القبــض هكــذا قــررا‬\n‫فبنــاء علــى مــا تقــدم مــن اإلدعــاء واإلجابــة ومــا قــرره األطــراف علــى‬\n‫مــا جــاء يف دعــوى املدعــي العــام وألن املدعــى عليــه األول أقــر بالترويــج‬\n‫وألنــه ال عــذر ملــن أقــر ونظــر ًا ملــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه بعاليــه ونظــر ًا ألن املدعــى عليــه االول ‪..........‬يســتحق العقوبــة‬\n‫طبق ـ ًا للقواعــد الشــرعية ووفق ـ ًا للمــواد (‪ )56-53-41-38‬مــن نظــام‬\n‫مكافحــة املخــدرات وحيــث أقــر املدعــى عليــه وليــد بالترويــج وأنكــر‬\n‫املدعــى عليــه الثانــي و الثالــث وقــد أحضــر املدعــي العــام البينــة وهــي‬\n‫غيــر موصلــة وهــي تفيــد الشــبهة لوجودهمــا يف مــكان اجلرميــة ولكــون‬\n‫ا قبيحــا وجــرأة يف الباطــل وإعانــة‬     ‫ا محرمــا وفعـ ً‬ ‫هــذا الفعــل يعــد عمـ ً‬\n‫علــى اإلثــم والعــدوان وإفســاد ًا يف األرض وألن املدعــى عليهــم لــم يعثــر‬\n\n\n                                                                                          ‫‪84‬‬\n\f     ‫لهــم علــى ســوابق وألن املدعــى عليــه األول أقــر بالتعاطــي للحشــيش‬\n     ‫وهــو مــن املســكرات حلديــث ( كل مســكر خمــر وكل خمــر حــرام)‬\n     ‫رواه مســلم وجلميــع مــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه األول‬\n     ‫ببيــع (‪ )1001.5‬ألــف وواحــد جــرام وخمســة أعشــار اجلــرام مــن مــادة‬\n     ‫احلشــيش املخــدر بقصــد الترويــج والشــروع يف ترويجهــا وتعاطيــه لنوعهــا‬\n     ‫مــن الســابق وتوجيــه الشــبهة إلــى املدعــى عليــه الثانــي ‪..........‬والثالــث‬\n     ‫‪..........‬باالشــتراك يف حيــازة الكميــة املضبوطــة بقصــد الترويــج عــن‬\n     ‫طريــق املســاعدة والشــروع يف ترويجهــا والشــبهة باشــتراكهم يف حيــازة‬\n     ‫مشــرط ومقــص عليهمــا أثــار ملــادة احلشــيش املخــدر وعليــه حكمــت‬\n     ‫مبــا يلــي ‪ :‬أوال‪ -:‬ســجن املدعــى عليــه األول ‪ ..........‬ملــدة ســنة ونصــف‬\n     ‫يحتســب منهــا مــدة اإليقــاف وجلــده ثمانــن جلــدة علنـ ًا دفعــة واحــدة حــد‬\n     ‫املســكر لقــاء تعاطيــه احلشــيش املخــدر وجلــده مائــة جلــدة تعزيــر ًا علنـ ًا‬\n     ‫مفرقــة علــى فترتــن مناصفــة بينهمــا عشــرة أيــام وبــن احلــد والتعزيــر‬\n     ‫عشــرة أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا ألــف ريــال ومصــادرة‬\n     ‫الهاتــف اجلــوال املشــار إليــه يف الدعــوى وبيعــه وإيــداع ثمنــه يف بيــت مــال‬\n     ‫املســلمني ويصــرف يف أوجــه البــر وإبعــاده خــارج اململكــة بعــد انتهــاء‬\n     ‫تنفيــذ عقوبتــه وعــدم الســماح لــه بالعــودة إليهــا إال مــا تســمح بــه تعليمــات‬\n     ‫احلــج والعمــرة ثانيــا‪ -:‬ســجن املدعــى عليــه الثانــي ‪..........‬للشــبهة ملــدة‬\n     ‫ثالثــة أشــهر حتتســب منهــا مــدة اإليقــاف وجلــده خمســون جلــدة تعزيــر ًا‬\n     ‫علن ـ ًا دفعــة واحــدة ثالث ـاً‪ -:‬ســجن املدعــى عليــه الثالــث ‪..........‬للشــبهة‬\n     ‫ملــدة ثالثــة أشــهر حتتســب منهــا مــدة اإليقــاف وجلــده خمســون جلــدة‬\n     ‫تعزيــر ًا علن ـ ًا دفعــة واحــدة وبعــرض احلكــم علــى املدعــى عليهــم قــرروا‬\n     ‫القناعــة واملدعــي العــام قــرر عــدم القناعــة وطلــب اســتئناف احلكــم‬\n\n\n‫‪85‬‬\n\f‫بــدون الئحــة اعتراضيــة حــرر يف ‪1434 / 01 /05‬ه ـ واغلقــت اجللســه‬\n‫الســاعه ‪ 10:30‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                            ‫وســلم‬\n‫احلمــد هلل وحــده وبعــد ـ ففــي يــوم االثنــن املوافــق ‪1434/1/19‬ه ـ‬\n‫أفتتحــت اجللســه الســاعه ‪ 11‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــه باخلطــاب رقــم ‪ 332196556‬يف‬\n‫‪1434/1/4‬ه ـ حيــث جــرى تدقيــق احلكــم مــن قبــل الدائــرة اجلزائيــة‬\n‫الرابعــه مبحكمــة االســتئناف واملظهــر علــى القــرار برقــم ‪33481901‬‬\n‫يف ‪1433/12/29‬ه ـ ونصــه ‪(-:‬وبدراســة القــرار وصــورة ضبطــه تقــررت‬\n‫املوافقــه علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ‪..........‬ختــم وتوقيــع قاضــي‬\n‫اســتئناف‪..........‬ختم وتوقيــع رئيــس الدائــرة ‪..........‬ختــم وتوقيــع ) وبيــان‬\n‫للواقــع جــرى احلاقــه بضبطــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبه وســلم واغلقت اجللســة الســاعه ‪ 11:15‬حرر يف ‪1434/1/19‬هـ‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‬\n\n\n\n\n                                                                                      ‫‪86‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":77,"source_page_end":86,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"35502b70a16b7d140c2849677b44842850a1ba55bc0550ee6974055dd745332a","normalized_text_hash":"042d9c2b4a284f971699ac49bf3aea83995d4bea7986356b2b048c9d90df0764","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p77-3420010"},{"id":"5d78bb56-b694-5273-a817-86594b9c22f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي والترويج - التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال وإتاف الشريحة املستخدمان يف اجلرمية.","document_number":"3452993","case_number":"33453864","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي والترويج - التعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال وإتاف الشريحة املستخدمان يف اجلرمية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3452993 :‬تاريخه ‪1434/3/2:‬هـ‬\n                      ‫رقم الدعوى ‪33453864:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34699042‬تاريخه‪1434/5/13:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي والترويــج ‪-‬‬\n     ‫التعزيــر بالســجن واجللــد واملنــع مــن الســفر ومصــادرة اجلــوال وإتــاف‬\n                                       ‫الشــريحة املســتخدمان يف اجلرميــة‪.‬‬\n\n\n\n\n     ‫‪ -1‬الفقــرة ‪ 1‬مــن املــادة ‪ 38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة‬\n     ‫‪ -2‬الفقــرة ‪ 1‬مــن املــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة‬\n     ‫‪ -3‬الفقــرة ‪ 1‬مــن املــادة ‪ 62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة‬\n     ‫‪ -4‬الفقــرة ‪ 1‬مــن املــادة ‪ 53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                      ‫العقليــة‬\n     ‫‪ -5‬تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬يف‬\n                                                                 ‫‪1428 /2 /1‬ه ـ‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة احلبــوب احملظــورة لقصــد‬\n     ‫التعاطــي والترويــج وتعاطيــه للحبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام‬\n\n‫‪87‬‬\n\f‫إثبــات مــا أســند إليــه واحلكــم بعقوبــة الســجن واجللــد والغرامــة واملنــع‬\n‫مــن الســفر و مصــادرة الهاتــف اجلــوال والشــريحة املســتخدم يف اجلرميــة‪،‬‬\n‫مت القبــض علــى املدعــى عليــه بعــد ورود إخباريــة مــن أحــد املصــادر‬\n‫الســرية مفادهــا وجــود شــخص يــروج احلبــوب احملظــورة بأحــد األســواق‬\n‫فتــم التنســيق مــع املصــدر لإلطاحــة بــه ومت تســليمه املبلــغ احلكومــي‬\n‫املرقــم وقــام املصــدر باالتفــاق مــع املدعــى عليــه وتقابــل املصــدر واملدعــى‬\n‫عليــه يف املوقــع احملــدد ومتــت عمليــة االســتالم والتســليم‪ ،‬قبــض عليــه‬\n‫وأقــر املدعــى عليــه بالدعــوى‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n‫بتعزيــره بالســجن واجللــد واملنــع مــن الســفر ومصــادرة اجلــوال وإســقاط‬\n‫الشــريحة املســتخدمان يف اجلرميــة وصــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا‪ ..........‬القاضــي باحملكمــة اجلزائيــة بالدمــام ففــي يــوم األربعــاء‬\n‫املوافــق ‪1433/9/6‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــر والنصــف‬\n‫ظهــرا بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالدمــام برقــم ‪ 33453864‬وتاريــخ ‪1433/7/8‬ه ـ واملقيــدة‬\n‫بــوارد مكتبنــا برقــم ‪ 331285113‬وتاريــخ ‪1433/7/8‬ه ـ واملتعلقــة‬\n‫بدعــوى املدعــي العــام ضــد ‪ ..........‬وفيهــا حضــر املدعــي العــام ‪...............‬‬\n‫وادعــى علــى احلاضــر معــه‪ ...............‬ســعودي اجلنســية بالبطاقــة رقم ‪.......‬‬\n‫قائــا يف دعــواه بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n‫باملنطقــة الشــرقية أدعــي علــى املذكــور أعــاه باإلطــاع علــى واقعــة‬\n\n                                                                                          ‫‪88‬‬\n\f     ‫القبــض والضبــط والتفتيــش يتضــح انــه يف متــام الســاعة التاســعة مــن‬\n     ‫مســاء األربعــاء املوافــق ‪1433/6/18‬ه ـ توفــرت معلومــات عــن شــخص‬\n     ‫يدعــى‪ ........ /‬يقــوم بترويــج حبــوب الكبتاجــون يف احــد احملــات‬\n     ‫التجاريــة بالدمــام فتــم التنســيق مــع احــد املصــادر وطلــب املصــدر‬\n     ‫مــن املــروج أغــراض مببلــغ مائــة وخمســن ريــال فتــم ترقيــم املبلــغ‬\n     ‫احلكومــي بعــد االتفــاق علــى املــكان ثــم نــزل املصــدر بعــد حضــور‬\n     ‫املــروج مترجــا واحتــك باملصــدر وســلمه املصــدر املبلــغ احلكومــي‬\n     ‫واســتلم املــادة املروجــة التــي اتضــح أنهــا ثــاث حبــات كبتاجــون فتــم‬\n     ‫القبــض علــى املــروج وعثــر علــى املبلــغ احلكومــي كامــا يف جيــب‬\n     ‫ثوبــه األيســر كمــا عثــر علــى تســع حبــات ونصــف احلبــة ممــا يشــتبه‬\n     ‫أن تكــون حبــوب كبتاجــون محظــورة يف يــده االيســرى أثبــت التقريــر‬\n     ‫الكيمــاوي الشــرعي رقــم (‪ )............‬يف ‪1433/6/25‬ه ـ إيجابيــة العينــة‬\n     ‫املرســلة حلبــوب األمفيتامــن احملظــور واملــدرج ضمــن اجلــدول (‪ )2‬فئــة‬\n     ‫(ب) املرفــق بنظــام املخــدرات (اســتهلكت العينــة يف التحليل)وضبــط‬\n     ‫معــه علــى جهــاز جــوال ‪ ......‬وباســتجوابه أقــر بصحــة واقعــة الضبــط‬\n     ‫وانــه طلــب منــه احــد األشــخاص حبــوب كبتاجــون وقــام ببيعــه ثــاث‬\n     ‫حبــات كبتاجــون مببلــغ مبائــة وخمســن ريــال وانــه عثــر بيــده اليســرى‬\n     ‫علــى تســع حبــات ونصــف احلبــة كبتاجــون بهــدف التعاطــي ثــم واقــر‬\n     ‫بتعاطيــه حبــوب الكبتاجــون وان أخــر مــرة تعاطهــا يــوم القبــض عليــه‬\n                           ‫وقد انتهى التحقيق إلى اتهام ‪ ................ /‬باآلتي ‪:‬‬\n               ‫‪ -1‬بيع (‪ )3‬ثالث حبات من حبوب االمفيتامني لقصد االجتار‬\n     ‫‪ -2‬حيازة(‪)9.5‬تســع حبــات ونصــف احلبــة مــن حبــوب االمفيتامــن‬\n                                                           ‫لقصــد التعاطــي والترويــج‬\n\n\n‫‪89‬‬\n\f                           ‫‪ -3‬تعاطي حبوب االمفيتامني املنبهة و احملظورة ‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬محضــر القبــض والضبــط والتفتيــش املــدون علــى الصفحــة رقــم‬\n                                 ‫(‪ )11‬مــن ملــف ضبــط إجــراءات االســتدالل‬\n         ‫‪ -2‬ما جاء يف أقواله حتقيق ًا املرفقة يف اللفتني رقم ( ‪.) 12-11‬‬\n                                ‫‪ -3‬محضر التحريز املرفق على اللفة رقم (‪)5‬‬\n           ‫‪ -4‬التقرير الكيماوي الشرعي املرفق على اللفة رقم ( ‪.) 13‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n                              ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب‬\n                                                                          ‫باآلتي ‪-:‬‬\n‫أو ًال ‪ :‬إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام‬\n                            ‫مكافحــة املخــدرات واحلكــم عليــه مبــا يلــي ‪-:‬‬\n‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )38‬مــن نظــام مكافحــة املخــدرات والتشــديد عليــه لترويجــه مــادة‬\n‫احلبــوب املخــدرة وفقــا للفقــرة (‪/2‬ج) مــن املــادة (‪ )38‬مــن ذات النظــام‬\n         ‫مــع مرعــاة املــادة(‪ )62‬مــن ذات النظــام بتطبيــق العقوبــة االشــد‬\n       ‫‪ -2‬منعه من السفر وفق الفقرة رقم (‪ )1‬من املادة (‪)56‬من النظام‪.‬‬\n‫ثالثا‪/‬مصــادرة جهــاز اجلــوال املوصــوف يف قــرار االتهــام الســتخدامه يف‬\n‫عمليــة الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن ذات‬\n‫النظــام عــدم صــرف الشــريحة لنفــس املتهــم وفقــا لتعميــم صاحــب‬\n‫السمو امللكي وزير الداخلية رقم ( ‪ ) 9798‬وتاريخ ‪1428/2/10-9‬هـ‬\n                                                                       ‫هذه دعواي‬\n‫ا ‪ ،‬مــا ذكــره املدعــي‬     ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ َ‬\n\n\n                                                                                          ‫‪90‬‬\n\f     ‫العــام مــن أننــي قمــت ببيــع (‪ )3‬ثــاث حبــات مــن حبــوب االمفيتامــن‬\n     ‫فصحيــح إال أن ذلــك لــم يكــن بقصــد االجتــار ‪ ،‬ومــا ذكــره املدعــي‬\n     ‫العــام مــن أننــي قمــت بحيــازة (‪ )9.5‬تســع حبــات ونصــف احلبــة مــن‬\n     ‫حبــوب االمفيتامــن فصحيــح إال أن ذلــك كان بقصــد التعاطــي ولــم‬\n     ‫يكــن بقصــد الترويــج ‪ ،‬ومــا ذكــره املدعــي العــام مــن أننــي أتعاطــى‬\n     ‫احلبــوب املنبهــة واحملظــورة فصحيــح هكــذا أجــاب ؛ ثــم جــرى اطالعــي‬\n     ‫علــى الســوابق املســجلة علــى املدعــى عليــه واملرفقــة باملعاملــة لفــة رقــم‬\n     ‫‪12‬وهــي ‪ -1‬محاولــة ســرقة ‪ -2‬تهمــة ســرقة ‪ -3‬االتــاف وبعرضهــا علــى‬\n     ‫املدعــى عليــه صــادق علــى صحتهــا‪ ،‬ثــم جــرى ســؤال املدعــي العــام هــل‬\n     ‫ا ‪ ،‬ليــس لــدي ســوى مــايف أوراق‬      ‫لديــك بينــة علــى دعــواك فأجــاب قائـ ً‬\n         ‫املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب وعليــه رفعــت اجللســة‪.‬‬\n     ‫وتأجلــت إلــى يــوم االثنــن املوافــق ‪1433/11/8‬ه ـ الســاعة التاســعة‬\n     ‫والنصــف صباح ـ ًا وختمــت اجللســة يف الســاعة الواحــدة ظهــر ًا واهلل‬\n     ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                        ‫‪1433/9/6‬ه ـ‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ففــي‬\n     ‫يــوم االثنــن املوافــق ‪1433/11/8‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n     ‫عشــر والنصــف صباح ـ ًا وفيهــا حضــر الطرفــان ثــم طلبــت مــن املدعــي‬\n     ‫العــام إحضــار البينــة لســماع مالديهــا مــن شــهادة عليــه رفعــت اجللســة‬\n     ‫وتأجلــت إلــى يــوم األحــد املوافــق ‪1433/11/28‬ه ـ الســاعة احلادية عشــر‬\n     ‫والنصــف صباحـ ًا وختمــت اجللســة يف الســاعة الثانيــة عشــر ظهــرا وعلــى‬\n     ‫ذلــك جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1433/11/8‬ه ـ‬\n\n\n‫‪91‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعد فلدي أنا‬\n‫‪ ...........‬القاضــي باحملكمــة اجلزائيــة بالدمــام ففــي يــوم األحــد املوافــق‬\n‫‪1434/03/01‬ه ـ افتتحــت اجللســة الســاعة العاشــرة والنصــف صباحــا‬\n‫وفيهــا حضــر الطرفــان ثــم جــرى ســؤال املدعــى عليــه عــن اجلــوال الــذي‬\n‫اتصــل املصــدر عليــه منــه فأجــاب قائــا هــو جوالــي ويعــود ملكيتــه لــي‬\n‫والرقــم الــذي بــه هــو رقمــي هكــذا أجــاب وقــد جــرى اطالعــي علــى‬\n‫أوراق املعاملــة كمــا جــرى اطالعــي علــى التقريــر الكيماوي الشــرعي‬\n‫رقــم ‪ ............‬وتاريــخ ‪1433/06/25‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪-17‬‬\n‫‪ )18‬واملتضمــن ثبــوت إيجابيــة احلبــوب جميعــا كال علــى حــده ملــادة‬\n‫اإلمفيتامــن احملظــورة املــدرج يف نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا ملــا قــرره‬\n‫الطرفــان ومــا مت رصــده وضبطــه أعــاه ونظــرا إلقــرار املدعــى عليــه‬\n‫بقيامــه ببيــع (‪ )3‬ثــاث حبــات مــن حبــوب اإلمفيتامــن وإقــراره بحيــازة‬\n‫مــا بلــغ وزنــه (‪ )9.5‬تســع حبــات ونصــف احلبــة مــن حبــوب اإلمفيتامــن‬\n‫بقصــد التعاطــي وإقــراره بتعاطيــه للحبــوب املنبهــة واحملظــورة واملــرء‬\n‫مؤاخــذ بإقــراره وال عــذر ملــن أقــر ونظــرا إلــى أن مــا قــام بــه املدعــى عليــه‬\n‫هــو محــرم شــرعا ومجــرم نظامــا وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ونظــرا‬\n‫لقلــة الكميــة ونظــرا ملــا ظهــر لــي مــن أخــاق املدعــى عليــه وبنــاء علــى‬\n‫الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة والتــي تقتضــي النــزول عــن احلــد األدنــى مــن عقوبــة‬\n‫الســجن املنصــوص عليهــا يف املــادة (الثامنــة والثالثــن) وبنــاء علــى‬\n‫الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                           ‫‪92‬‬\n\f     ‫واملؤثــرات العقليــة واملتضمنــة بأنــه إذا ارتكــب شــخص عــدة جرائــم‬\n     ‫معاقــب عليهــا مبوجــب أحــكام نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة قبــل صــدور حكــم نهائــي بحقــه عــن أي واحــدة منهــا وجــب‬\n     ‫محاكمتــه علــى اجلرميــة ذات العقوبــة األشــد واحلكــم بعقوبتهــا دون‬\n                                                              ‫غيرهــا ولــكل مــا ســبق ‪:‬‬\n     ‫(أوالً)‪:‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن قيامــه ببيــع (‪)3‬‬\n                          ‫ثــاث حبــات مــن حبــوب االمفيتامــن وبذلــك حكمــت‬\n                                  ‫وحكمت على املدعى عليه لقاء ذلك مبا يلي ‪:‬‬\n     ‫(‪ )1‬حكمــت علــى املدعــى عليــه بســجنه ســنتني ونصــف يحتســب‬\n     ‫منهــا مــا أمضــاه موقوفــا يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪)1‬‬\n     ‫مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n     ‫ووفق ـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة‬\n                                                      ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n                 ‫(‪ )2‬حكمت على املدعى عليه بجلده مائتني وخمسني جلدة‬\n     ‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا‬\n                                                                             ‫عشــرة أيــام‬\n     ‫وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقم (‪ )38‬من نظام مكافحة املخدرات‬\n     ‫واملؤثــرات العقلية‪.‬وهــذه العقوبــة شــاملة لتعاطــي املدعــى عليــه للحبــوب‬\n                                                                     ‫املنبهــة و احملظورة ‪.‬‬\n          ‫(‪ )3‬حكمت على املدعى عليه بدفع غرامة مالية وقدرها ألف ريال‬\n     ‫وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n                                                       ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n     ‫(‪)4‬حكمــت علــى املدعــى عليــه مبنعــه مــن الســفر إلــى خــارج اململكــة‬\n\n\n‫‪93‬‬\n\f‫بعــد انتهــاء عقوبــة الســجن ملــدة ســنتني ونصــف وفقــا للفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫(‪ )5‬حكمــت علــى املدعــى عليــه مبصــادرة هاتفــه اجلــوال املســتخدم يف‬\n‫الترويــج واملذكــور يف الئحــة دعــوى املدعــي العــام وذلــك وفقــا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                            ‫العقليــة‪.‬‬\n‫(‪ )6‬حكمــت علــى املدعــى عليــه بإســقاط شــريحته املســتخدمة يف‬\n‫الترويــج واملذكــورة يف الئحــة دعــوى املدعــي العــام وعــدم صرفهــا‬\n‫للمتهــم نفســه وذلــك بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقــم ( ‪)9798‬‬\n                                                   ‫وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n‫(ثاني ـاً)‪ :‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن تعاطيــه‬\n‫للحبــوب املنبهــة واحملظــورة وبذلــك حكمــت وعقوبــة ذلــك داخلــة يف‬\n                                      ‫الفقــرة رقــم (‪ )2‬مــن البنــد رقــم(أوالً)‬\n‫(ثالثــا) ثبــت لــدي إدانــة املدعــى عليــه بحيــازة مابلــغ وزنــه (‪ )9.5‬تســع‬\n‫حبــات ونصــف احلبــة مــن حبــوب االمفيتامــن بقصــد التعاطــي وتســقط‬\n‫العقوبــة يف ذلــك إعمــا ًال للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليه قناعتــه باحلكم وقرر‬\n‫املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة ورفعــه‬\n‫حملكمــة االســتئناف وعليــه فقــد قــررت رفــع املعاملــة كاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم وختمــت يف الســاعة احلاديــة عشــرة صباحــا‬\n‫وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪14 34 /03/01‬ه ـ ‪.‬‬\n\n\n                                                                                         ‫‪94‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫يــوم الســبت املوافــق ‪1434/05/18‬ه ـ افتتحــت اجللســة الســاعة الواحدة‬\n     ‫ظهــر ًا وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n     ‫الشــرقية بخطــاب رئيــس محكمــة االســتئناف رقــم ‪34/699042‬‬\n     ‫وتاريــخ ‪1434/05/13‬ه ـ وبرفقهــا القــرار رقــم ‪ 34207641‬وتاريــخ‬\n     ‫‪1434/05/06‬ه ـ الصــادر مــن قضــاة الدائــرة اجلزائيــة األولــى وهــم‬\n     ‫فضيلــة الشــيخ‪ ،...... /‬وفضيلــة الشــيخ ‪ ، ........ /‬وفضيلــة الشــيخ ‪/‬‬\n     ‫‪ ،..........‬واملتضمــن املصادقــة علــى احلكــم وللمعلوميــة فقــد جــرى‬\n     ‫حتريــره وختمــت يف الســاعة العاشــرة والنصــف صباحـ ًا وبــاهلل التوفيــق‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n                                                                  ‫يف ‪1434/05/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n     ‫‪ 33/1285113‬وتاريــخ ‪1434/3/16‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪/34/699042‬ج‪ 1‬وتاريــخ ‪1434/3/21‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ......‬املســجل برقــم ‪3452993‬‬\n     ‫وتاريــخ ‪1434/3/2‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ........ /‬يف‬\n     ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرارو صــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434/5/5‬ه ـ‬\n\n\n\n‫‪95‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":87,"source_page_end":95,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66486f0519dfa7e001a34c5697608cb7696ddfe53c34974ba44409f6ab3c4bfd","normalized_text_hash":"259e04428a1d75c5c961b5cafd590a3bf9ee6894c29f25a94477b879280883c4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p87-3452993"},{"id":"bf7caf27-41cb-5156-8b8c-2f46b8122251","document_type":"judgment","category":"judicial","subcategory":"general","title":"حيازة الهيروين املخدر -احليازة بقصد االجتار -الشروع يف بيع الهيروين املخدر -تعاطي الهيروين املخدر -تستر -إقامة حد املسكر على متعاطي الهيروين املخدر -التعزير بالسجن واجللد واملنع من","document_number":"33388788","case_number":"33455562","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/21","year":"1434","subject":"حيازة الهيروين املخدر -احليازة بقصد االجتار -الشروع يف بيع الهيروين املخدر -تعاطي الهيروين املخدر -تستر -إقامة حد املسكر على متعاطي الهيروين املخدر -التعزير بالسجن واجللد واملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33388788:‬تاريخه ‪1433/8/21:‬هـ‬\n                  ‫رقم الدعوى ‪33455562:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34589034‬تاريخه‪1434/04/20:‬هـ‬\n\n\n‫حيــازة الهيرويــن املخــدر‪ -‬احليــازة بقصــد االجتــار‪ -‬الشــروع يف بيــع‬\n‫الهيرويــن املخــدر‪ -‬تعاطــي الهيرويــن املخــدر‪ -‬تســتر‪ -‬إقامــة حــد املســكر‬\n‫علــى متعاطــي الهيرويــن املخــدر‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن‬\n                                                                      ‫الســفر ‪.‬‬\n\n\n\n\n‫‪-1‬الفقــرة األولــى مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملوثــرات‬\n                                                                       ‫العقلية‪.‬‬\n‫‪-2‬الفقــرة األولــى مــن املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملوثــرات‬\n                                                                       ‫العقلية‪.‬‬\n\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بحيــازة‬\n‫الهيرويــن املخــدر بقصــد االجتــار والشــروع يف بيعــه وتعاطــي الهيرويــن‬\n‫املخــدر وتســتره علــى مــروج املــواد املخــدرة‪ ،‬وطلــب املدعــي العــام إثبــات‬\n‫مــا أســند إليــه واحلكــم بعقوبــه الســجن واجللــد والغرامــة والتشــديد‬\n‫عليــه كونــه رجــل أمــن ومنعــه مــن الســفر ومصــادرة الهاتــف اجلــوال‬\n‫وإلغــاء الشــريحة املســتخدمة باجلرميــة وإلــزام املدعــى عليــه بإعــادة‬\n‫املبلــغ املرقــم‪ ،‬مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا أن‬\n\n                                                                                     ‫‪96‬‬\n\f     ‫املدعــى عليــه يقــوم بترويــج الهيرويــن املخــدر ومت التنســيق مــع أحــد‬\n     ‫املصــادر الســرية لإليقــاع باملدعــى عليــه متلبس ـ ًا وبعــد حضــور املصــدر‬\n     ‫ملوقــع املدعــى عليــه مت القبــض علــى املدعــى عليــه قبــل عمليــه االســتالم‬\n     ‫والتســليم ووجــد بجيبــه كيــس بــه مــادة صفــراء وتبــن أنهــا هيرويــن‬\n     ‫مخــدر‪ ،‬إقــرار املدعــى عليــه بتعاطــي الهيرويــن املخــدر وحيــازة الهيروين‬\n     ‫لقصــد االســتعمال ونفــي مــا ســوى ذلــك‪ ،‬إحضــار املدعــى العــام بينــة‬\n     ‫غيــر موصلــة يف أثبــات الترويــج‪ ،‬توجيــه التهمــة للمدعــى عليــه مبــا نســب‬\n     ‫إليــه‪ ،‬إقامــة حــد املســكر وتعزيــر املدعــى عليــه بالســجن واجللــد واملنــع‬\n     ‫مــن الســفر‪ ،‬رد مطالبــة املدعــى العــام مبصــادرة الهاتــف اجلــوال لعــدم‬\n                   ‫ثبــوت الترويــج‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 33455562‬وتاريــخ ‪1433/07/09‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331291307‬وتاريــخ ‪ 1433/07/09‬ه ـ ففــي‬\n     ‫يــوم اإلثنــن املوافق‪1433/07/14‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n     ‫وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى علــى احلاضــر معــه الســجني‬\n     ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬بقولــه حيــث‬\n     ‫أنــه باإلطــاع علــى احملضــر املعــد مــن قبــل شــعبة مكافحــة املخــدرات‬\n     ‫بالدمــام بتاريــخ يــوم الثالثــاء املوافــق ‪1433/5/18‬ه ـ تبــن انــه مت‬\n     ‫القبــض علــى املدعــى عليــه اثــر بــاغ عــن قيامــه بالتوســط والترويــج‬\n     ‫للمــواد املخــدرة وانــه يســتخدم لذلــك اجلــوال رقــم (‪ )......‬وبنــاء عليــه مت‬\n\n‫‪97‬‬\n\f‫متكــن املصــدر مــن االتصــال عليــه وطلــب منــه كميــه مــن الهيرويــن‬\n‫املخــدر فذكــر لــه املتهــم انــه ( ابشــر عنــدي باكســتاني بــس أنــا‬\n‫ينتهــي دوامــي الســاعة ثمانيــة ونتقابــل عنــد البيــت ) ويف الســاعة الثامنــة‬\n‫مت تزويــد املصــدر ببطاقــة شــحن بقيمــه ( ‪ ) 300‬ريــال ومت تفتيــش‬\n‫املصــدر تفتيشــا دقيقــا وعنــد الوصــول إلــى املوقــع قــام املدعــى عليــه‬\n‫بالركــوب مــع املصــدر بســيارته ومت متابعتهمــا حتــى توقفــا خلــف‬\n‫إحــدى محطــات البنزيــن باخلبــر الشــمالية ونــزل املتهــم مــن الســيارة‬\n‫وتوجــه إلــى زاويــة احــد املنــازل والتقــط شــي مــا كان يف األرض‬\n‫ومت القبــض عليــه بعــد ذلــك ومت العثــور بحوزتــه علــى بطاقــة الشــحن‬\n‫وكيــس صغيــر بداخلــه مــادة علــى شــكل بــودرة بلــغ وزنهــا (‪ )6.7‬ســتة‬\n‫جرامــات وســبع أعشــار اجلــرام اثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ 1963‬ش ) وتاريخ‪1432/5/24‬ه ـ ايجابيتهــا ملــادة الهيرويــن املخــدر‬\n‫وباســتجوابه أنكــر قيامــه ببيــع الهيرويــن املخــدر وأضــاف انــه يف ذلــك‬\n‫اليــوم اتصــل بــه شــخص يعرفــه وطلــب منــه الهيرويــن املخــدر بقصــد‬\n‫التعاطــي وبعــد ذلــك ذكــر لــه أن ســيارته متعطلــة فقــام باملــرور عليــه‬\n‫وتوجهــا إلــى الســوق لشــراء بعــض األغــراض مــن هنــاك ويف أثنــاء‬\n‫تواجدهــم قــام بالتقــاط الهيرويــن املخــدر الــذي ســبق وقــام باالتفــاق مــع‬\n‫شــخص باكســتاني علــى وضعــه لــه وقــام بأخــذه بــدون علــم مرافقــه‬\n‫وبعــد ذلــك مت القبــض عليــه وبحوزتــه الهيرويــن املخــدر وأضــاف انــه‬\n‫قــام باحلصــول علــى الهيرويــن عــن طريــق الشــحن لذلــك الشــخص‬\n‫الباكســتاني وأفــاد إن وجــوده برفقتــه كان بغــرض توصيلــه فقــط ولــم‬\n‫يتفــق معــه علــى شــراء املــواد املخــدرة لــه وأقــر بتعاطيــه للهيرويــن املخــدر‬\n‫وانتهــى التحقيــق إلــى توجيــه االتهــام ل ـ ‪ ........‬بحيــازة مــا وزنــه (‪)6.7‬‬\n\n\n                                                                                         ‫‪98‬‬\n\f     ‫ســتة جرامــات وســبع أعشــار اجلــرام بقصــد االجتــار والشــروع يف بيعهــا‬\n     ‫وبتعاطــي الهيرويــن املخــدر وتســتره علــى مــروج املــواد املخــدرة وذلــك‬\n     ‫لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا ورد يف أقوالــه ‪ -2‬محضــر الضبــط‬\n     ‫والتفتيــش ‪ -3‬التقريــر الكيميائــي الشــرعي وبالبحــث عمــا إذا كان‬\n     ‫لــه ســوابق عثــر لــه علــى ســابقتني األولــى حيــازة واســتعمال مخــدرات‬\n     ‫والثانيــة شــرب املســكر وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n     ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n     ‫إثبــات مــا أســند إليــه وفق ـ ًا للفقــرة رقــم (‪ )2‬ورقــم (‪ ) 7‬مــن املــادة (‪)3‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واحلكــم عليــه مبــا يلــي ‪ -1 -:‬عقوبــة‬\n     ‫الســجن واجللــد والغرامــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن‬\n     ‫نظــام مكافحــة املخــدرات ووفــق املــادة (‪ ) 59‬مــن النظــام والتشــديد‬\n     ‫عليــه كونــه رجــل امــن اســتناد ًا إلــى برقيتــي صاحــب الســمو امللكــي‬\n     ‫وزيــر الداخليــة رقــم (‪ )112103 /4/5/1‬وتاريــخ ‪1429/11/4‬هــ‪،‬‬\n     ‫ورقــم ‪ 10130/4/5/1‬وتاريخ‪1429/2/15‬ه ـ والتشــديد عليــه لترويجــه‬\n     ‫ملــادة الهيرويــن املخــدرة وفــق الفقــرة (‪/2‬ج) مــن املــادة (‪ ) 38‬مــع مراعــاة‬\n     ‫املــادة (‪ )62‬مــن النظــام ‪2 .‬ـ منعــه مــن الســفر وفق ـ ًا للفقــرة (‪ )1‬مــن‬\n     ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‪3.‬ـ مصــادرة الهاتــف اجلــوال‬\n     ‫ذو الرقــم أملصنعــي ( ‪ )............‬املســتخدم يف عمليــة الترويــج تطبيق ـ ًا‬\n     ‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات مــع إســقاط‬\n     ‫رقــم شــريحة اجلــوال املســتخدم يف عمليــه الترويــج وفقــا لتعميــم ســمو‬\n     ‫وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10‬ه ـ ثاني ـاً‪ :‬مطالبــه املتهــم‬\n     ‫بإعــادة املبلــغ احلكومــي املرقــم تطبيقــا لتعميــم ســمو وزيــر الداخليــة‬\n     ‫رقــم (‪ )15980/4/5/1‬وتاريــخ ‪1428/10/ 23-22‬ه ـ هكــذا ادعــى‬\n\n\n‫‪99‬‬\n\f‫وبطلبــي مــن املدعــى عليــه اإلجابــة أجــاب قائــا مــا ذكــره املدعــي‬\n‫العــام مــن قيامــي بالتوســط يف ترويــج الهيرويــن غيــر صحيــح والصحيــح‬\n‫إننــي كنــت قــد ذهبــت برفقــة املصــدر بعــد أن اتصــل بــي وطلبــت منــه‬\n‫إيصالــي للســوق ألن ســيارتي متعطلــة ولــم يكــن يعــرف عــن اتفاقــي مــع‬\n‫الباكســتاني بشــأن الهيرويــن ألنــي لــم أكــن أنــوي أن أعطــي مرافقــي‬\n‫أي شــي منــه والهيرويــن املضبــوط معــي كان لالســتعمال الشــخصي‬\n‫وليــس للترويــج فقــد كنــت اشــتريته مــن الباكســتاني وذلــك مقابــل‬\n‫بطاقــة شــحن مببلــغ ثالثمائــة ريــال وأنــا أتعاطــى الهيرويــن منــذ ســبع‬\n‫ســنوات تقريب ـ ًا وســوابقي املذكــورة يف الدعــوى صحيحــة و غيــر‬\n‫صحيــح أنــي متســتر علــى الباكســتاني فأنــا ال أعــرف وســيلة للتواصــل‬\n‫معــه إال باالتصــال عليــه وأقــوم بشــحن بطاقــة اتصــال لــه ثــم يضــع‬\n‫الهرويــن لــي يف مــكان متفــق عليــه بيننــا لكنــي لــم أقابلــه و ال أعرفــه‬\n‫وال أعــرف مقــر ســكنه هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة‬\n‫جــرى االطــاع علــى مــا يلــي ‪ :‬أوالً‪ /‬التقريــر الكيمــاوي الشــرعي رقــم‬\n‫‪1963‬ك ش واملتضمــن ايجابيــة العينــة املرســلة ملــادة الهيرويــن املخــدر‬\n‫ثانيــا‪ /‬محضــر التحريــز املتضمــن مــا يلــي ( جــرى حتريــز املضبوطــات‬\n‫املدونــة يف محضــر الضبــط والتــي ضبطــت بحيــازة املدعــو‪ ....... /‬وهــي‬\n‫عبــارة عــن كيــس بــه مســحوق اصفــر اللــون يــزن بالغــاف اخلارجــي تزن‬\n‫( ‪ )6.7‬ســتة جرامــات وســبعة مــن العشــرة يشــتبه أن تكــون هيرويــن‬\n‫مخــدر ) ثالثـ ًا ‪ /‬أقــوال املدعــى عليــه حتقيقـ ًا املتضمنــة مــا يلــي نصــه ‪،‬‬\n‫س‪ :‬أنــت متهــم بالتوســط يف ترويــج الهيرويــن املخــدر مــا هــو قولــك ؟‬\n‫ج‪ :‬ال أنــا لــم أقــوم بالتوســط يف ترويــج الهيرويــن ‪ .‬س‪ :‬مــا هــو غرضــك‬\n‫يف الهيرويــن الــذي ضبــط معــك ؟ ج‪ :‬اســتعمال شــخصي فقــط س‪ :‬مــا‬\n\n\n                                                                                      ‫‪100‬‬\n\f      ‫عالقــة زميلــك الــذي كان معــك يف الســيارة حــن القبــض عليــك ؟ ج‪:‬‬\n                                   ‫عالقتــي كان معــي وأنــا وهــو نتعاطــى الهيرويــن‬\n      ‫املخــدر وليــس لــه عالقــة ‪ .‬س‪ :‬متــى آخــر مــرة تعاطيــت فيهــا املخــدر؟ ج‪:‬‬\n      ‫قبــل بليلــة تعاطيــت ‪ ،‬هــذا وبطلبــي مــن املدعــي العــام البينــة طلــب إمهالــه‬\n      ‫و رفعــت اجللســة لذلــك ويف جلســة اخــرى حضــر املدعــي العــام ‪ .....‬ولــم‬\n      ‫يتــم احضــار الســجني ‪ .......‬وحضــر للشــهادة وادائهــا ‪ ....‬ســجله (‪)......‬‬\n      ‫وبســؤاله عمــا لديــه قــال وردنــا بــاغ عــن احــد االشــخاص يقــوم بالترويــج‬\n      ‫عــن طريــق احــد مصادرنــا الســرية فتــم متكــن املصــدر مــن مكاملــة‬\n      ‫املدعــى عليــه لكنــي لــم اســمع املكاملــة ثــن توجهــت مــع املصــدر ملقابلــة‬\n      ‫املدعــى عليــه لالطاحــة بــه وكان املوعــد املتفــق عليــه بــن املدعــى‬\n      ‫عليــه واملصــدر عنــد بيــت املدعــى عليــه نزلــت الســيارة وقمــت بتفتيــش‬\n      ‫املصــدر وســيارته للتحقــق مــن عــدم حملــه الي شــيء مــن املمنوعــات‬\n      ‫ابــراء للذمــة ومت تســليم املصــدر بطاقــة شــحن مببلــغ (‪ )300‬ريــال وهــي‬\n      ‫قيمــة الهيرويــن املخــدر املــروج حســب اتفــاق املصــدر مــع املدعــى عليــه‬\n      ‫ثــم ابتعــدت للمراقبــة ثــم حتركنــا ملتابعــة املصــدر مــن ‪ ....‬إلــى ‪ ......‬ثــم‬\n      ‫نــزل املدعــى عليــه مــن الســيارة فنزلــت ملراقبتــه ثــم مشــى قليــا وهــو‬\n      ‫يتكلــم بالســيارة وقــام بالتقــاط شــيء مــن علــى االرض ثــم عــاد وركــب‬\n      ‫الســيارة ثــم قمــت مبداهمتــه قبــل امتــام عمليــة االســتالم والتســليم‬\n      ‫وقمــت باخــراج كيــس مــن جيبــه بداخلــه مــادة صفــراء قمــت بســحبها‬\n      ‫وحتريزهــا وتبــن انهــا هيرويــن مخــدر هــذا مالــدي وبــه اشــهد كمــا‬\n      ‫حضــر للشــهادة وادائهــا ‪ .....‬ســجله (‪ )......‬وبســؤاله عمــا لديــه قــال اشــهد‬\n      ‫هلل تعالــى انــي شــاركت يف متابعــة املدعــى عليــه وقــد شــاهدته ينــزل‬\n      ‫مــن ســيارة املصــدر وهــو يتحــدث باجلــوال والتقــط شــيء مــن االرض ثــم‬\n\n\n‫‪101‬‬\n\f‫عــاد الســيارة والن الشــارع مزدحــم وخشــية مــن هروبــه اعطيــت االشــارة‬\n‫للمداهمــة وقمنــا بالقبــض عليــه وقــد قــام الشــاهد األول باســتخراج‬\n‫كيــس مــن جيبــه بداخلــه مــادة صفــراء اللــون مت حتريزهــا واثبــت‬\n‫التقريــر الكيمــاوي ايجابيتهــا ملــادة احلشــيش املخــدر هــذا مالدينــا‬\n‫وبــه نشــهد هــذا وبطلبــي مــن املدعــي العــام زيــادة بينــة قــال ليــس لــدي‬\n‫ســوى مــايف أوراق املعاملــة هكــذا قــرر هــذا وحضــر لتعديــل الشــاهدين‬\n‫‪ ......‬ســجله (‪ ).....‬وشــهد بعدالــة وثقــة الشــاهدين هكــذا شــهد وعليــه‬\n‫جــرى التوقيــع ورفعــت اجللســة الحضــار معــدل ثانــي للشــاهدين ويف‬\n‫جلســة اخــرى حضــر ‪ ....‬ســجله (‪ )......‬وقــرر قائــا اشــهد بعدالــة وثقــة‬\n‫الشــاهدين ‪ ......‬و ‪ .......‬هكــذا شــهد وتأجلــت اجللســة الحضــار املدعــى‬\n‫عليــه ويف جلســة اخــرى حضــر املدعــي العــام ‪ ......‬و املدعــى عليــه ‪.......‬‬\n‫وبعــرض الشــهود و شــهادته علــى املدعــى عليــه قــال الشــهود ال أعرفهــم‬\n‫وشــهادتهم غيــر صحيــح ‪ ،‬والصحيــح أن املصــدر طلــب منــي هرويــن‬\n‫للتعاطــي فأجبتــه أنــه ليــس لــدي هرويــن و ألنــي أتعاطــى الهرويــن املخــدر‬\n‫و ألن ســيارتي متعطلــة طلبــت منــه أن ميــر علــي يف بيتــي ثــم ذهبــت معــه‬\n‫بســيارته حتــى آخــذ الهرويــن املخــدر لــي شــخصيا و ليــس للمصــدر و‬\n‫غرضــي مــن أخــذ الهرويــن و حيازتــه هــو االســتخدام الشــخصي و ليــس‬\n‫للبيــع أو الترويــج و غيــر صحيــح أنــي اســتلمت بطاقــة شــحن مــن املصــدر‬\n‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث أقــر‬\n‫املدعــى عليــه بتعاطــي الهرويــن املخــدر و حيــازة قطعــة هرويــن مخــدر‬\n‫بلــغ وزنهــا ســتة جرامــات و ســبعة بالعشــرة مــن اجلــرام أثبــت التقريــر‬\n‫الكيمــاوي إيجابيتهــا للهرويــن املخــدر بقصــد االســتعمال الشــخصي‬\n‫وحيــث أنكــر أن يكــون حيازتــه للمــادة املضبوطــة معــه بقصــد االجتــار‬\n\n\n                                                                                     ‫‪102‬‬\n\f      ‫والشــروع يف بيعها و حيث أن الشــهود لم تتضمن شــهادتهم قيام املدعى‬\n      ‫عليــه بتســليم املصــدر قطعــة الهرويــن املخــدر وال اســتالمه لبطاقــة‬\n      ‫الشــحن لــذا فقــد ثبــت لــدي شــرعا إدانــة املدعــى عليــه بتعاطــي الهرويــن‬\n      ‫املخــدر و حيــازة قطعــة هرويــن مخــدر بقصــد االســتعمال و لــم يثبــت‬\n      ‫لــدي شــرعا إدانــة املدعــى عليــه بقصــد االجتــار و الشــروع يف بيعهــا مــن‬\n      ‫حيــازة قطعــة الهرويــن لعــدم كفايــة األدلــة و تتوجــه عليــه التهمــة يف أن‬\n      ‫القصــد مــن احليــازة هــو االجتــار و الشــروع يف بيعهــا وذلــك ملــا ورد يف‬\n      ‫أقوالــه حتقيقــا علــى محضــر االســتجواب (لفــة ‪ )19‬مــن اتصــال شــخص‬\n      ‫بــه و طلــب منــه هرويــن مخــدر بغــرض التعاطــي و طلبــه منــه املــرور‬\n      ‫عليــه و مرافقتــه للمصــدر يف التوجــه للحصــول علــى الهرويــن املخــدر‬\n      ‫و إحضــاره مــن املوقــع املتفــق عليــه بينــه و بــن املــروج كل ذلــك يقــوي‬\n      ‫التهمــة املوجهــة إليــه و حكمــت عليــه باآلتــي‪ ]1[ :‬حــده علــى تعاطــي‬\n      ‫الهرويــن املخــدر بحــد املســكر بجلــده ثمانــن جلــدة دفعــة واحــدة علنــا‬\n      ‫و يف مــكان عــام [‪ ]2‬تعزيــره علــى حيــازة قطعــة احلشــيش املخــدر وفقــا‬\n      ‫للفقــرة األولــى مــن املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات و املؤثــرات‬\n      ‫العقليــة بســجنه ســتة أشــهر تبــدأ اعتبــارا مــن تاريــخ ســجنه [‪ ]3‬منعــه‬\n      ‫مــن الســفر وفقــا للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مــدة ســنتني‬\n      ‫تبــدأ اعتبــارا مــن تاريــخ خروجــه مــن الســجن [‪ ]4‬تعزيــره علــى التهمــة يف‬\n      ‫احليــازة بقصــد االجتــار و الشــروع يف بيعهــا بســجنه خمســة أشــهر تبــدأ‬\n         ‫اعتبــارا مــن انتهــاء محكوميتــه اخلاصــة بســجنه علــى احليــازة بقصــد‬\n      ‫االســتعمال الشــخصي و جلــده مائتــي جلــدة مفرقــة علــى أربــع دفعــات‬\n      ‫متســاويات بــن كل دفعــة و األخــرى اســبوع و يفــرق بــن جلــد احلــد‬\n      ‫وجلــد التعزيــر بأســبوع [‪ ]5‬رد مطالبــة املدعــي العــام مبصــادرة الهاتــف‬\n\n\n‫‪103‬‬\n\f‫اجلــوال للمدعــى عليــه ورد مطالبتــه بإســقاط الشــريحة لعــدم ثبــوت‬\n‫قصــد الترويــج مــن احليــازة و عــدم ثبــوت الشــروع يف البيــع إذ ال يحكــم‬\n‫باملصــادرة إال حــال الثبــوت [‪ ]6‬رد مطالبــة املدعــي العــام باحلكــم علــى‬\n‫املتهــم بــرد املبلــغ احلكومــي املرقــم لعــدم ثبوت اســتالمه لبطاقة الشــحن‬\n‫وبعــرض احلكــم علــى املدعــي العــام قــرر املعارضــة و قــرر املدعــى عليــه‬\n‫القناعــة بــه وصلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم حــرر يف‬\n                                                                    ‫‪1433/7/23‬هـ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االربعــاء املوافــق ‪1434/2/20‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11.10‬بنــاء علــى ورود املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 332070150‬يف ‪1434/1/27‬ه ـ‬\n‫وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة االولــى برقــم‬\n‫قــرار ‪ 3413288‬يف ‪1434/1/17‬ه ـ و نــص احلاجــة منــه (وبدراســة‬\n‫القــرار وصــور ضبطــه وأوراق املعاملــة لوحــظ أن صــورة الضبــط‬\n‫اخلاصــة بشــهادة الشــاهدين لــم ترفــق مــن ضمــن طيــات املعاملــة وعلــى‬\n‫فضيلتــه إرفــاق صــورة الضبــط كاملــة ملالحظــه مــا ذكــر واكمــال‬\n‫الــازم ومــن ثــم اعــادة املعاملــة) عليــه اجيــب اصحــاب الفضيلــة انــه جــرى‬\n‫ارفــاق صــورة الضبــط اخلاصــه بشــهادة الشــاهدين وللبيــان جــرى إحلاقــه‬\n‫بضبطــه وإعــادة املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل‬\n                                                                            ‫التوفيــق‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 34/267695‬وتاريــخ ‪1434/3/7‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n\n\n                                                                                         ‫‪104‬‬\n\f      ‫‪/34/589037‬ج‪ 1‬وتاريــخ ‪1434/3/8‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ......‬املســجل برقــم ‪ ............‬وتاريــخ‬\n      ‫‪1433/8/21‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ......../‬يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع علــى مــا‬\n      ‫أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى‬\n      ‫قرارنــا رقــم‪ /3413288‬ج‪/1‬ب يف ‪1434/1/17‬ه ـ قررنــا املصادقــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                            ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/4/13‬ه ـ‬\n\n\n\n\n‫‪105‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":96,"source_page_end":105,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a47bd389dcb09522baf7e8ff506f4e5ae8c21e797bc2a47142ae51550a071c3a","normalized_text_hash":"c50cafe203ea2cb1656d4e3776fb30cf4f18c66ff6814f17ab7f1c3eebadd852","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p96-33388788"},{"id":"9b2e2977-d5e9-559f-b64a-dbcb6ae31348","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة -تعاطي احلبوب احملظورة بقصد الترويج والتعاطي إقرار مصدق شرع ا -رجوع عن اإلقرار- إثبات إدانة مبوجب إقرار مصدق شرع ا -تعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة هاتف جوال مستخدم يف اجلرمية -إلغاء شريحة جوال مستخدم يف اجلرمية -إلزام بإعادة املبلغ املرقم.","document_number":"33351045","case_number":"33465667","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/21","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة -تعاطي احلبوب احملظورة بقصد الترويج والتعاطي إقرار مصدق شرع ا -رجوع عن اإلقرار- إثبات إدانة مبوجب إقرار مصدق شرع ا -تعزير بالسجن واجللد والغرامة واملنع من السفر -مصادرة هاتف جوال مستخدم يف اجلرمية -إلغاء شريحة جوال مستخدم يف اجلرمية -إلزام بإعادة املبلغ املرقم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33351045:‬تاريخه ‪1433/7/21:‬هـ‬\n                   ‫رقم القضية ‪33465667:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 33432343‬تاريخه‪1433/10/21:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة احلبــوب احملظــورة‪ -‬تعاطــي احلبــوب احملظــورة‬\n‫بقصــد الترويــج والتعاطــي إقــرار مصــدق شــرع ًا‪ -‬رجــوع عــن اإلقــرار‪-‬‬\n‫إثبــات إدانــة مبوجــب إقــرار مصــدق شــرع ًا‪ -‬تعزيــر بالســجن واجللــد‬\n‫والغرامــة واملنــع مــن الســفر‪ -‬مصــادرة هاتــف جــوال مســتخدم يف‬\n‫اجلرميــة‪ -‬إلغــاء شــريحة جــوال مســتخدم يف اجلرميــة‪ -‬إلــزام بإعــادة‬\n                                                              ‫املبلــغ املرقــم‪.‬‬\n\n\n\n\n‫‪ -1‬املــادة ‪ 13‬مــن الفقــرة ‪ 2‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n ‫‪ -2‬املادة ‪ 38‬الفقرة ‪ 1‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n‫‪ -3‬املــادة ‪ 56‬مــن الفقــرة ‪ 1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n  ‫‪ -4‬املادة ‪ 53‬الفقرة ‪1‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n            ‫‪ -5‬املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n ‫‪ -6‬املادة ‪ 62‬الفقرة ‪ 1‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n   ‫‪ -7‬تعميم سمو وزير الداخلية رقم ‪ 1/5/4/29290‬يف ‪1431/5/7‬هـ‪.‬‬\n\n\n\n\n                                                                                   ‫‪106‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام بترويــج عــدد‬\n      ‫ثــاث حبــات محظــورة بقصــد الكســب املــادي وحيــازة حبتــن محظــورة‬\n      ‫بقصــد التعاطــي وتعاطــي احلبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام‬\n      ‫إثبــات مــا أســند إليــه و احلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n      ‫املاليــة ومنعــه مــن الســفر ومصــادرة هاتفــه اجلــوال وشــريحته املســتخدمة‬\n      ‫يف اجلرميــة وعــدم صرفهــا وإرجــاع املبلــغ احلكومــي املرقــم‪ ،‬حيــث‬\n      ‫إنــه مت القبــض علــى املدعــى عليــه بعــد إخباريــة مفادهــا قيــام أحــد‬\n      ‫األشــخاص بترويــج احلبــوب احملظــورة ومت متكــن املصــدر مــن االتصــال‬\n      ‫بــه والتنســيق معــه علــى هاتفــه اجلــوال ثــم تقابــل املصــدر مــع املتهــم و‬\n      ‫قبــض عليــه بعــد عمليــة االســتالم والتســليم‪ ،‬أقــر املدعــى عليــه بحيــازة‬\n      ‫احلبــوب لغــرض االســتخدام وأنكــر املدعــى عليــه احليــازة لغــرض‬\n      ‫الترويــج‪ ،‬وجــود إقــرار للمدعــى عليــه بترويــج ثــاث حبــات محظــورة‪،‬‬\n      ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بثبــوت إدانــة املدعــى عليــه‬\n      ‫وبتعزيــره بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال‬\n      ‫والشــريحة املســتخدمان يف اجلرميــة وإلزامــه بإعــادة املبلــغ املرقــم‪ ،‬صــدق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬رئيــس احملكمــة العامــة باجلبيــل‬\n      ‫بنــاء علــى املعاملــة الــواردة لنــا مــن دائــرة التحقيــق واالدعــاء العــام‬\n      ‫باجلبيــل برقــم ه ـ ق ‪ 1338/3/6‬بتاريــخ ‪1433/7/14‬ه ـ واملقيــدة لدينــا‬\n\n‫‪107‬‬\n\f‫برقــم ‪ 331324928‬بتاريــخ ‪1433/7/14‬ه ـ واحملالــة ملكتبنــا برقــم‬\n‫‪ 33465667‬ففــي هــذا اليــوم االثنــن ‪1433/7/21‬ه ـ متــام الســاعة‬\n‫التاســعة افتتحــت اجللســة وفيهــا حضــر املدعــي العــام ‪ ......‬ســجل مدنــي‬\n‫‪ ......‬كمــا حضــر املدعــى عليــه ‪ .......‬ســعودي اجلنســية بالســجل املدنــي‬\n‫رقــم ‪ ............‬وادعــى املدعــي العــام بدعــواه احملــررة يف أوراق املعاملــة‬\n‫ونصهــا‪ :‬إنــه بتاريــخ ‪1433/6/10‬ه ـ وبنــاء علــى املعلومــات الــواردة إلــى‬\n‫وحــدة مكافحــة املخــدرات مبحافظــة اجلبيــل مــن إحــدى مصادرهــا‬\n‫الســرية عــن قيــام أحــد األشــخاص بترويــج احلبــوب احملظــورة وبنــاء‬\n‫عليــه مت متكــن املصــدر مــن االتصــال علــى ذلــك الشــخص علــى الهاتــف‬\n‫رقــم (‪ )......‬فقــال املصــدر كــم يف املائتــي ريــال قــال أربــع ويبقــى لــك‬\n‫ثالثــة فوافــق املصــدر فتــم تفتيشــه وتزويــده مببلــغ مرقــم (‪ )200‬مائتــي‬\n‫ريــال ومت االنتقــال معــه برفقــة املــازم‪ ....... /‬إلــى شــارع‪ ........‬وحضــر‬\n‫ذلــك الشــخص علــى ســيارة مــن نــوع ‪ ........‬حتمــل اللوحــة رقــم (‪ )......‬مت‬\n‫تســليمها لوالــده كونهــا تعــود لشــركة ‪ ........‬لتأجيــر الســيارات وقــام‬\n‫باالحتــكاك مــع املصــدر وغــادر وبعــد ســاعة قــام املصــدر باالتصــال‬\n‫علــى ذلــك الشــخص وقــال لــه نتقابــل عنــد البنــك ‪ ............‬وحضــر وقــام‬\n‫بتســليم عــدد (‪ )3‬ثــاث حبــات للمصــدر يشــتبه أن تكــون مــن احلبــوب‬\n‫احملظــورة فتــم مراقبتــه والقبــض عليــه وقــد أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي رقــم (‪ 24180‬ك ش) وتاريــخ ‪1433/6/25‬ه ـ إيجابيــة احلبــوب‬\n‫املضبوطــة وباســتجوابه أقــر بصحــة واقعــة القبــض عليــه مــن قبــل‬\n‫مكافحــة املخــدرات بعــد ترويجــه عــدد (‪ )3‬ثــاث حبــات مــن حبــوب‬\n‫الكبتاجــون احملظــورة وحيازتــه علــى عــدد (‪ )2‬حبتــن مــن حبــوب‬\n‫الكبتاجــون احملظــورة وهــي تعــود لــه شــخصيا وقصــده مــن حيازتهــا‬\n\n                                                                                     ‫‪108‬‬\n\f      ‫التعاطــي الشــخصي وأقــر انــه حصــل عليهــا مــن شــخص ال يعرفــه مببلــغ‬\n      ‫(‪ )200‬ريــال كمــا أقــر بأنــه يتعاطــى احلبــوب احملظــورة منــذ حوالي ســتة‬\n      ‫أشــهر وصــادق علــى أقوالــه شــرعا وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫لــه بترويــج عــدد (‪ )3‬ثالثــة حبــات مــن حبــوب اإلمفيتامــن احملظــورة‬\n      ‫بقصــد الكســب املــادي وحيــازة عدد (‪ )2‬حبتني مــن حبوب اإلمفيتامني‬\n      ‫احملظــورة بقصــد التعاطــي وتعاطيــه لــذات النــوع وذلــك إلقــراره املصــدق‬\n      ‫شــرعا واملــدون علــى الصفحــة رقــم (‪ )6‬مــن دفتــر التحقيــق املرفــق‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق جنائيــة لــم يعثــر لــه ســوابق مســجلة‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ونظامــا أطلــب إثبــات مــا اســند‬\n      ‫إليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة املنصــوص عليهــا‬\n      ‫يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام املخــدرات واملؤثــرات‬\n      ‫العقليــة ومنعــه مــن الســفر إلــى خــارج اململكــة وفقــا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )56‬مــن النظــام املشــار إليــه ومصــادرة الهاتــف النقــال‬\n      ‫مــن نــوع (‪ ).....‬يحمــل الرقــم املصنعــي (‪ )............‬املســتخدم يف عمليــة‬\n      ‫الترويــج وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات‬\n      ‫وإلغــاء الشــريحة املتعلقــة بالرقــم املســتخدم يف اجلرميــة وعــدم صرفهــا‬\n      ‫للمدعــى عليــه وإرجــاع املبلــغ املرقــم وقــدره (‪ )200‬ريــال وإيداعــه يف‬\n      ‫حســاب اإلدارة العامــة ملكافحــة املخــدرات وتشــديد العقوبــة عليــه‬\n      ‫لترويجــه احلبــوب احملظــورة هــذه دعــواي‪ .‬ثــم جــرى عــرض دعــوى‬\n      ‫ا مــا ذكــره املدعــي‬   ‫املدعــي العــام علــى املدعــى عليــه فأجــاب قائ ـ ً‬\n      ‫العــام يف دعــواه فيمــا يتعلــق باحليــازة والتعاطــي للحبــوب احملظــورة فهــو‬\n      ‫صحيــح فقــد مت القبــض علــي بالتاريــخ املذكــور وبحوزتــي حبتــان مــن‬\n\n‫‪109‬‬\n\f‫الكبتاجــون وقــد تعاطيــت مثلهــا يف وقتهــا أمــا مــا ذكــره فيمــا يتعلــق‬\n‫بالترويــج فهــو غيــر صحيــح وأنــا اآلن موقــوف يف ذمــة هــذه القضيــة‬\n‫هــذه إجابتــي‪ .‬وبســؤال املدعــي العــام عــن بينتــه قــال نعــم لــدي البينــة‬\n‫وهــي اعتــراف املدعــى عليــه املصــدق شــرع ًا املرفــق باملعاملــة ثــم جــرى‬\n‫الرجــوع إلــى أوراق املعاملــة ومــن بينهــا اعتــراف املدعــى عليــه املصــادق‬\n‫عليــه شــرع ًا املــدون علــى الصحيفــة رقــم ‪ 6‬مــن دفتــر التحقيــق لفــة رقــم‬\n‫‪ 8‬ونصــه‪ :‬نعــم أنــا املوقــع أدنــاه وبــدون إجبــار أو أكــراه مــن احــد اقــر‬\n‫باحلقيقــة التاليــة أقــر إننــي قمــت بترويــج عــدد ثــاث حبــات كبتاجــون‬\n‫علــى أحــد األشــخاص مببلــغ مائتــان ريــال واقــر إننــي اســتلمت مبلــغ‬\n‫مائتــان ريــال مــن احــد األشــخاص وهــو املبلــغ احلكومــي املرقــم وذهبــت‬\n‫علــى ســيارتي نــوع ‪ ....‬لوحــة رقــم (‪ )......‬إلــى ‪ ........‬واشــتريت عــدد خمــس‬\n‫حبــات كبتاجــون ورجعــت إلــى اجلبيــل علــى نفــس الســيارة وقمــت‬\n‫بتســليم املشــتري عــدد ثــاث حبــات التــي روجتهــا وبقيــت معــي حبتــان‬\n‫واقــر أنهــا ضبطــت يف جيبــي اخلــاص بالبدلــة التــي كنــت ألبســها وأقــر‬\n‫أنهــا لــي لقصــد التعاطــي كمــا أقــر أننــي اشــتريت هــذه احلبــوب مــن‬\n‫شــخص ال أعرفــه وأقــر أنــي أتعاطــى احلبــوب مــن حوالــي ســتة أشــهر‪.‬‬\n‫إبهــام املقــر مبــا فيــه وبعرضــه علــى املدعــى عليــه قــال نعــم صحيــح‬\n‫هــذه االعتــراف ولكنــه قــد أخــذ منــي بالقــوة واإلكــراه فجــرى ســؤاله‬\n‫هــل لديــك بينــة علــى ذلــك فقــرر أنــه ال بينــة لديــه علــى دعــوى اإلكــراه‬\n‫وبعــد ســماع الدعــوى واإلجابــة جــرى االطــاع علــى التقريــر الكيمــاوي‬\n‫الشــرعي املرفــق باملعاملــة لفــة ‪ 11‬واملتضمــن إيجابيــة احلبــوب احملــرزة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬‫ملــادة االمفيتامــن احملظــور‪ .‬فبنـ ً‬\n‫واعتــراف املدعــى عليــه املصــدق شــرع ًا ومــا جــرى االطــاع عليــه ممــا‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫نــوه عنــه أعــاه وألن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم شــرع ًا‬\n      ‫يســتحق معــه العقوبــة والتأديــب وملــا جــاء يف املــادة ‪ 3‬الفقــرة ‪ 2‬واملــادة ‪38‬‬\n      ‫الفقــرة ‪ 1‬واملــادة ‪ 56‬الفقــرة ‪ 1‬واملــادة ‪ 53‬الفقــرة ‪ 1‬واملــادة ‪ 62‬الفقــرة‬\n      ‫‪1‬مــن نظــام املخــدرات واملؤثــرات العقليــة وملــا جــاء يف تعميــم وزيــر‬\n      ‫الداخليــة رقــم ‪ 29290/4/5/1‬يف ‪1431/5/7‬ه ـ فقــد قــررت مــا يلــي‪:‬‬\n      ‫أو ًال ثبــت لــدي إدانــة املدعــى عليــه بقيامــه بترويــج مــا عــدده ثــاث حبــات‬\n      ‫مــن حبــوب الكبتاجــون بقصــد الكســب املــادي كمــا ثبتــت لــدي إدانة‬\n      ‫املدعــى عليــه بحيازتــه حلبيتــن مــن حبــوب الكبتاجــون بقصــد التعاطــي‬\n      ‫وتعاطيــه مــن ذات النــوع ســابقاً‪ .‬ثانيـ ًا تعزيــر املدعــى عليــه وذلــك بســجنه‬\n      ‫خمــس ســنوات اعتبــار ًا مــن تاريــخ إيقافــه يف ذمــة هــذه القضيــة وجلــده‬\n      ‫مائتــي جلــدة مفرقــة علــى أربــع دفعــات متســاويات يف عــدد اجللــدات علــى‬\n      ‫أن يكــون بــن تنفيــذ كل دفعــة وأخــرى فتــرة ال تقــل عــن أســبوع إلزامــه‬\n      ‫بدفــع غرامــة قدرهــا ألــف ريــال ثالثـ ًا منــع املدعــى عليــه مــن الســفر مــدة‬\n      ‫خمــس ســنوات اعتبــار ًا مــن انتهــاء فتــرة محكوميتــه بخصــوص هــذه‬\n      ‫القضيــة رابع ـ ًا مصــادرة الهاتــف النقــال املســتخدم يف عمليــة الترويــج‬\n      ‫وإيــداع قيمتــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات وإلغــاء‬\n      ‫الشــريحة املتعلقــة بالرقــم املســتخدم يف اجلرميــة وعــدم صرفهــا للمدعــى‬\n      ‫عليــه وألزمــت املدعــى عليــه بإرجــاع مبلــغ مائتــي ريــال وذلك مقابــل املبلغ‬\n      ‫املرقــم وإيداعــه يف حســاب اإلدارة العامــة ملكافحــة املخــدرات‪ .‬وبجميــع‬\n      ‫مــا تقــدم حكمــت‪ .‬وبعرضــه علــى الطرفــن قــرر املدعــي العــام قناعتــه‪.‬‬\n      ‫أمــا املدعــى عليــه فقــرر عــدم القناعــة وطلــب رفــع احلكــم حملكمــة‬\n      ‫االســتئناف بــدون الئحــة وأجبتــه لطلبــه وعليــه جــرى التوقيــع وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1433/6/22‬هــ‪.‬‬\n\n\n‫‪111‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االحــد املوافــق ‪1434/1/4‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة العاشــرة والنصــف وفيهــا حضــر املدعي‬\n‫العــام واملدعــى عليــه‪ .‬وفيهــا وردت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية برقــم ‪ 33/1428098‬وتاريــخ ‪1433/11/9‬ه ـ‬\n‫املتضمنــة قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة االولــى برقــم‬\n‫‪ 33432343‬وتاريــخ ‪1433/10/21‬ه ـ ومضمونــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة لوحــظ ان فضيلتــه حكــم علــى املدعــى‬\n‫عليــه بســجنه مــدة خمــس ســنوات اال يــرى فضيلتــه ان احلكــم علــى‬\n‫املدعــى عليــه بذلــك كثيــر الســيما مــع قلــة الكميــة وخلــو ســجله مــن‬\n‫الســوابق اســتنادا للمــادة ‪ 60‬مــن نظــام مكافحــة املخــدرات‪ .‬ونظــرا‬\n‫لوجاهــة مــا ذكــره أصحــاب الفضيلــة وملــا ذكــروه مــن مســوغات‬\n‫لتخفيــف احلكــم بخصــوص الســجني واســتنادا للمــادة ســتني مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة لــذا فانــي ال زلــت علــى مــا‬\n‫حكمــت بــه ســابقا ســوى عقوبــة الســجن يف الفقــرة ثانيــا فقــد رجعــت‬\n‫عمــا حكمــت بــه فيمــا يتعلــق بعقوبــة الســجن وقــررت تعزيــر املدعــى‬\n‫عليه وذلك بســجنه ســنتني وســتة أشــهر اعتبارا من تاريخ ايقافه يف ذمة‬\n‫هــذه القضيــة وبجميــع مــا تقــدم حكمــت‪ .‬وبعرضــه علــى الطرفــن قــرر‬\n‫املدعــى عليــه القناعــة‪ .‬وقــرر املدعــي العــام عدمهــا وطلــب رفــع احلكــم‬\n‫حملكمــة االســتئناف بــدون الئحــة واجبتــه لطلبــه ‪ .‬وبــاهلل التوفيــق‬\n     ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر بتاريــخ ‪1434/1/4‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1434/3/16‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا وردت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية ‪ 3481566‬وتاريــخ ‪1434/2/26‬ه ـ متضمنــه قــرار‬\n\n\n                                                                                  ‫‪112‬‬\n\f      ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة االولــى برقــم ‪ 3438022‬يف‬\n      ‫‪1434/2/16‬ه ـ ومضمونــه حيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n      ‫وباالطــاع علــى مــا اجــاب بــه فضيلــة القاضــي واحلقــه بالقــرار وصــورة‬\n      ‫ضبطــه بنــاء علــى قرارنــا رقــم ‪/33432343‬ج‪/1‬ب يف ‪1433/10/21‬ه ـ‬\n      ‫قررنــا املصادقــة علــى احلكــم بعــد االجــراء االخيــر‪ .‬وبــاهلل التوفيــق‬\n         ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر بتاريــخ ‪1434/3/16‬هــ‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":106,"source_page_end":113,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d16a0b6b1caeeee9f7d0e3e727c7d258e065fedc1e8026ccf92a6aba0943e61b","normalized_text_hash":"f26774b52e7abc7884209ce074bb010c9e14aec444b5b4c3330aace4c2489f14","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p106-33351045"},{"id":"e2be8738-65fb-5ff6-a1b5-0cd9a51c1c0e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش املخدر بقصد الترويج والتعاطي- حيازة احلبوب احملظورة -تعاطي احلشيش املخدر -تستر -اإلقرار حتقيق ا -رجوع عن اإلقرار -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة املالية واملنع","document_number":"33409886","case_number":"33467488","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/12","year":"1434","subject":"مخدرات -حيازة احلشيش املخدر بقصد الترويج والتعاطي- حيازة احلبوب احملظورة -تعاطي احلشيش املخدر -تستر -اإلقرار حتقيق ا -رجوع عن اإلقرار -إثبات إدانة -إقامة حد املسكر على متعاطي احلشيش -تعزير بالسجن واجللد والغرامة املالية واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33409886:‬تاريخه ‪1433/09/12 :‬هـ‬\n                   ‫رقم الدعوى ‪33467488:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n       ‫‪1/70945‬ج‪ 34/‬تاريخه‪1434/03/24:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة احلشــيش املخــدر بقصــد الترويــج والتعاطــي‪-‬‬\n ‫حيــازة احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬تســتر‪ -‬اإلقــرار‬\n ‫حتقيق ـ ًا‪ -‬رجــوع عــن اإلقــرار‪ -‬إثبــات إدانــة‪ -‬إقامــة حــد املســكر علــى‬\n ‫متعاطــي احلشــيش ‪ -‬تعزيــر بالســجن واجللــد والغرامــة املاليــة واملنــع‬\n                                                                   ‫مــن الســفر‪.‬‬\n\n\n\n ‫املواد ‪ ،62 -60 -56 -38‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع قطعــة مــن احلشــيش املخــدر‬\n ‫بقصــد االجتــار والترويــج وحيــازة حبــوب البــروزوالم املهـ ّـدئ احملظــور‬\n ‫وســيجارة مخلــوط تبغهــا باحلشــيش املخــدر بقصــد الترويــج والتعاطــي‪،‬‬\n ‫وتعاطــي احلشــيش املخــدر واحلبــوب احملظــورة وتســتره علــى مصــدر‬\n ‫مــا باعــه ومــا مت ضبطــه‪ -‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه‬\n ‫و احلكــم بعقوبــة الســجن واجللــد والغرامــة املاليــة وإجــراء املقتضــى‬\n ‫الشــرعي حيــال تعاطيــه احلشــيش املخــدر و احلبــوب احملظــورة ومنعــه‬\n ‫مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء عقوبــة الســجن ومصــادرة‬\n ‫هاتفــه اجلــوال وإلغــاء شــريحته املســتخدمني يف اجلرميــة وعقوبــة تعزيريــة‬\n\n                                                                                     ‫‪114‬‬\n\f      ‫لقــاء تســتره علــى مصــدر مــا باعــه ومــا مت ضبطــه‪ ،‬حيــث إنــه مت القبــض‬\n      ‫علــى املدعــى عليــه بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج‬\n      ‫احلشــيش املخــدر فتــم التنســيق مــع أحــد املصــادر ومت اتفــاق املصــدر‬\n      ‫مــع املدعــى عليــه لشــراء قطعــة مــن احلشــيش وعنــد التقــاء املصــدر‬\n      ‫مــع املدعــى عليــه يف املــكان احملــدد ســلم املدعــى عليــه للمصــدر‬\n      ‫قطعــة مــن احلشــيش ومت القبــض عليــه قبــل تســليم املبلــغ مــن املصــدر‪،‬‬\n      ‫إنــكار املدعــى عليــه بيــع احلشــيش املخــدر وإنــكاره حيازتــه للحبــوب‬\n      ‫والســيجارة وإقــراره بتعاطــي احلشــيش املخــدر‪ ،‬وجــود إقــرار حتقيق ـ ًا‬\n      ‫للمدعــى عليــه‪ ،‬إثبــات إدانــة املدعــى عليــه مبــا نســب إليــه‪ ،‬بنــاء علــى‬\n      ‫مــا ســبق حكمــت احملكمــة بتعزيــره بالســجن واجللــد والغرامــة‪،‬‬\n      ‫إقامــة حــد املســكر واملنــع مــن الســفر ومصــادرة اجلــوال والشــريحة‬\n         ‫املســتخدمني يف اجلرميــة‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33467488‬وتاريــخ ‪1433/07/15‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331331946‬وتاريــخ ‪1433/07/15‬ه ـ ففــي يــوم‬\n      ‫اإلثنــن املوافــق ‪1433/08/26‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ........... .‬وادعــي علــى‪ .......... .. :‬البالــغ مــن‬\n      ‫العمــر ‪20‬عامــا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)......‬‬\n      ‫اعــزب طالــب يقيــم يف مدينــة الريــاض اوقــف بتاريخ‪1433/4/24‬ه ـ‬\n      ‫واحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيف رقم‬\n\n‫‪115‬‬\n\f‫(ه ـ ر‪ )52983/5/1‬وتاريــخ ‪1433/5/8‬ه ـ واســتنادا للقــرار الــوزاري‬\n‫رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة (‪ )112‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة حيــث انــه بتاريــخ ‪1433/4/24‬ه ـ قبــض علــى‬\n‫املذكــور مــن قبــل إحــدى فــرق شــعبة املكافحــة والبحــث والتحــري‬\n‫التابعــه ملكافحــة املخــدرات مبنطقــة الريــاض بنــاء علــى معلومــات مــن‬\n‫احــد املصــادر الســرية مفادهــا وجــود شــخص يدعــى ‪ .....‬يقــوم بترويــج‬\n‫احلشــيش املخدر ويتواجد على اجلوال رقم(‪ )......‬واملصدر على اســتعداد‬\n‫لإلطاحــة بــه باجلــرم املشــهود عليــه مت متكــن املصــدر مــن االتصــال علــى‬\n‫اجلــوال املــروج وطلــب منــه قطعــه من احلشــيش املخدر مببلــغ(‪ )200‬مائتي‬\n‫ريــال فوافــق املــروج علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى مطعــم‬\n‫‪ .......‬الواقــع علــى طريــق ‪ ....‬فتــم تفتيــش املصــدر وســيارته تفتيشــا‬\n‫دقيقــا ومت تزويــده باملبلــغ املرقــم وقــدره(‪ )200‬مائتــن ريــال ومت االنتقــال‬\n‫الــى املوقــع احملــدد وعنــد الوصــول حضــر شــخص يرتــدي قميــص نــوم‬\n‫واحتــك بالســياره التــي يســتقلها املصــدر عندهــا ســلم للمصــدر قطعــه‬\n‫يشــتبه ان تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )6،0‬ســتة جرامــات‬\n‫وقبــل تســلم املــروج املبلــغ املرقــم أحــس بتواجــد رجــال املكافحــه فحاول‬\n‫الهــرب فتمــت مداهمتــه وبضبطــه والســيطرة عليــه اتضــح أنــه املذكــور‬\n‫وعثــر معــه علــى جــوال مــن نــوع ‪ .......‬حمــل الرقــم املصنعــي (‪)............‬‬\n‫وهــو اجلــوال الــذي متــت عليــه عمليــة الترويــج وعثــر معــه علــى مبلــغ مالــي‬\n‫وقــدره (‪ )270‬مائتــان وســبعون ريــاال جــرى مبوجــب اخلطــاب رقــم (ه ـ‬\n‫ر ‪ )63420/5/1‬وتاريخ‪1433/6/8‬ه ـ عمــا مبقتضــى املــادة (‪ )86‬مــن‬\n‫نظــام اإلجــراءات اجلزائيــة كونــه ليــس الزمــا للســير يف الدعــوى وليــس‬\n‫محــا للمصــادرة وبتفتيــش مــكان وقوفــه عثــر علــى (‪ )30‬حبــة حتمــل‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫عالمــة (زنكــس) احملظــورة وكذلــك علــى ســيجارة مســتخدمة يشــتبه‬\n      ‫ان يكــون تبغهــا مخلــوط باحلشــيش املخــدر بلــغ وزنهــا (‪ )1،0‬جرامــا‬\n      ‫واحــدا وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n      ‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم‬\n      ‫(‪/4482‬س) لعــام ‪1433‬ه ـ ايجابيــة عينــة القطعــة املبيعــة ومســتخلص‬\n      ‫تبــغ الســيجارة املضبوطــة ملــادة احلشــيش وهــو مــن املــواد املخــدرة‬\n      ‫واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحتــواء عينــة احلبــوب املضبوطــة ملــادة البــروزوالم‬\n      ‫وهــو مــن املــواد املهدئــة واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبســماع أقوالــه األوليــة‬\n      ‫واســتجوابه اعتــرف ببيــع قطعــة احلشــيش املخــدر املبيعــة بحيــازة حبــوب‬\n      ‫الزنكــس احملضــورة وســيجارة احلشــيش املخــدر املضبوطــة بقصــد‬\n      ‫التعاطــي وتعاطيــة احلشــيش املخــدر واحلبــوب احملضــورة واســتخدامه‬\n      ‫جلوالــه يف عمليــة الترويــج ودون لــه إقــرار بذلــك ولــم يــدل مبعلومــات‬\n      ‫عــن مصــدر مــا روج ومــا ضبــط وقــد أســفرت إجــراءات التحقيــق عــن‬\n      ‫توجيــه األتهــام لــ‪ ...........‬ببيــع قطعــة مــن احلشــيش املخــدر تــزن (‪)6،0‬‬\n      ‫ســتة جرامــات بقصــد االجتــار والترويــج وحيــازة (‪ )30‬ثالثــون حبــه مــن‬\n      ‫حبــوب البــروزوالم املهــدئ احملظــور وســيجارة مخلــوط تبغهــا باحلشــيش‬\n      ‫املخــدر تــزن (‪ )1،0‬جرامــا واحــد ًا بقصــد الترويــج والتعاطــي وتعاطيــه‬\n      ‫احلشــيش املخــدر واحلبــوب احملظــورة املجــرم مبوجــب املــادة (الثالثــة)‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا‬\n      ‫باعــه ومــا مت ضبطــه املعاقــب علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن‬\n\n\n‫‪117‬‬\n\f‫التاليــة ‪ /1‬مــا تضمنــه إقــراره بدفتــر التحقيــق املنــوه عنــه املرفــق لفــه‬\n‫رقــم (‪ )16‬صفحــة رقــم (‪ /2 )3‬مــا تضمنــه اعترافــه حتقيق ـ ًا املنــوه‬\n‫عنــه علــى الصفحــات رقــم (‪ )2-1‬مــن دفتــر التحقيــق املرفــق لفــه رقــم‬\n‫(‪ /3 )16‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه‬\n‫عنــه املرفــق لفــه رقــم (‪ /4 )10‬مــا تضمنــه محضــر االنتقــال والقبــض‬\n‫والتفتيــش املنــوه عنــه املرفــق لفــه رقــم ( ‪/5)3-1‬مــا تضمنــه التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه رقــم (‪ )29‬وببحــث ســوابقه‬\n‫اتضــح عــدم وجــود ســوابق مســجله عليــه حتــى تاريخــه وحيــث أن مــا‬\n‫أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا‬\n‫أطلــب اثبــات ادانتــه مبــا أســند إليــه واحلكــم باآلتــي ‪ /1 :‬بعقوبــة‬\n‫الســجن واجللــد والغرامــة املاليــة بحقــه وفقــا للفقــرة (األولــى ) مــن املــادة‬\n‫(‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وأعمــال الفقــرة‬\n‫(األولــى ) مــن املــادة (‪ )62‬مــن ذات النظــام ‪/2‬إجــراء املقتضــى الشــرعي‬\n‫بحقــه لقــاء تعاطيــه احلشــيش املخــدر واحلبــوب احملظــورة ‪ /3‬منعــه مــن‬\n‫الســفر إلــى خــارج اململكــة بعــد إنتهــاء تنفيــذ عقوبــة ســجنه الفقــرة‬\n‫( األولــى ) مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة ‪ /4‬مصــادرة جهــاز اجلــوال ذو الرقــم املصنعــي (‪)............‬‬\n‫املســتخدم يف جرميــة الترويــج وفق ـ ًا للفقــرة األولــى مــن املــادة (‪ )53‬مــن‬\n‫نظــام مكافحــة املخــدرات املشــار إليــه ‪ /5‬إلغــاء الشــريحة ذات الرقــم‬\n‫(‪ ).........‬املســتخدمة يف عمليــة الترويــج وعــدم صرفهــا لنفــس املشــترك‬\n‫وإبــاغ الشــركة مصــدرة الشــريحة يف حــال صــدور احلكــم باإللغــاء‬\n‫بذلــك اســتناد ًا لتعميــم ســمو ولــي العهــد نائــب رئيــس مجلــس الــوزراء‬\n‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10 -9‬ه ـ ‪ /6‬عقوبــة‬\n\n\n                                                                                         ‫‪118‬‬\n\f      ‫تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا باعــه ومــا ضبــط هــذه‬\n      ‫دعــواي‪ ،‬بســؤال املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام‬\n      ‫يف دعــواه أننــي قمــت ببيــع قطعــة مــن احلشــيش املخــدر وحيــازة ثالثــن‬\n      ‫حبــه محظــورة وســيجارة مخلوطــة باحلشــيش املخــدر فذلــك غيــر صحيح‬\n      ‫ومــا ذكــره أننــي أتعاطــى احلشــيش املخــدر فذلــك صحيــح هــذه إجابتــي‬\n      ‫فجــرى ســؤال املدعــي العــام هــل لديــه بينــة علــى دعــواه قــال نعــم بينتــي‬\n      ‫مــا ذكــرت ومــا هــو موجــود يف أوراق املعاملــة ورفعــت اجللســة لدراســة‬\n      ‫أوراق املعاملــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/08/26‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض ففــي يــوم الثالثــاء املوافــق‪ 1433/09/12‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 12.50‬وفيهــا حضــر املدعــي العــام وحضــر املدعــى عليــه ‪.......‬‬\n      ‫وباالطــاع علــى أوراق املعاملــة وجــدت مــن ضمــن أوراقهــا لفــه رقــم (‪)10‬‬\n      ‫محضــر ســماع أقــوال املدعــى عليــه بتاريــخ ‪1433/4/24‬ه ـ اقــر فيــه‬\n      ‫املدعــى عليــه بترويــج احلشــيش املخــدر وحيــازة ســيجارة حشــيش وحبوب‬\n      ‫محظورة‪ ،‬ويف اللفة رقم (‪ )16‬ملف التحقيق املرفق يف الصفحة االولى‬\n      ‫والثانيــة منــه محضــر اســتجواب املدعــى عليــه لــدى هيئــة التحقيــق‬\n      ‫واالدعــاء العــام أقــر فيهــا املدعــى عليــه أنــه قــام ببيــع قطعــة حشــيش‬\n      ‫مخــدر تــزن ســته إجــرام وأقــر بحيــازة ســيجارة مســتخدمة مخلوطــة‬\n      ‫باحلشــيش املخــدر تــزن واحــد إجــرام وحيــازة ثالثــن حبــه محظــورة وأنــه‬\n      ‫اســتخدم الهاتــف اجلــوال املذكــور يف الدعــوى يف عمليــة الترويــج ويف‬\n      ‫الصفحــة الثالثــة مــن امللــف إقــرار املدعــى عليــه وهــذا نصــه ( أقــر أنــا ‪....‬‬\n      ‫وأنــا بكامــل قــواي العقليــة الشــرعية املعتبــرة أننــي قمــت بتســليم قطعــة‬\n\n\n‫‪119‬‬\n\f‫مــن احلشــيش املخــدر تــزن ( ‪)6.0‬ســتة جرامــات ومت القبــض علــي بعدهــا‬\n‫وذلــك بعــد أن تلقيــت ثالثــن حبــة زنكــس وســيجارة حشــيش مخــدرات‬\n‫تــزن واحــد جــرام واحــدة وهــي عائــدة لــي لغــرض االســتخدام وعلــى‬\n‫هــذا أوقــع ) وبعــرض هــذه االقــرارات علــى املدعــى عليــه قــال ‪ :‬بصمــت‬\n‫علــى هــذه االقــرارات واعترفــت بترويــج احلشــيش بســبب الضــرب الــذي‬\n‫تعرضــت لــه يف مكافحــة املخــدرات أمــا اعتــرايف لــدى هيئــة التحقيــق‬\n‫واالدعــاء العــام فقــد اعترفــت بالترويــج الننــي كنــت خائفــا فاعترفــت‬\n‫بالترويــج وقالــوا لــي ابصــم فبصمــت ولــم أتعــرض للضــرب واالكــراه‬\n‫يف هيئــة التحقيــق أ‪.‬ه ـ وبــن أوراق املعاملــة تقريــر كيميائــي يتضمــن‬\n‫ايجابيــة عينــة القطعــة املرســلة ومســتخلص تبــغ الســيجارة ملادة احلشــيش‬\n‫املخــدر واحتــواء احلبــوب املرســلة ملــادة البــروزوالم وهــو من املــواد املدرجة‬\n‫باجلــدول رقــم (‪ )2‬فئــة ( د) مــن نظــام مكافحــة املخــدرات ‪ ،‬فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة انــكار املدعــى عليــه ترويــج‬\n‫احلشــيش املخــدر وحيــازة ســيجارة مخلوطــة باحلشــيش املخــدر وحبــوب‬\n‫محظــورة ‪ ،‬واقــراره بتعاطــي احلشــيش املخــدر وحيــث أثبــت املدعــي‬\n‫العــام دعــواه بالبينــة وهــي إقــراره لــدى مكافحــة املخــدرات بترويــج‬\n‫قطعــة احلشــيش املخــدر املذكــورة يف الدعــوى وحيازة ســيجارة مخلوطة‬\n‫باحلشــيش املخــدر وحبــوب محظــورة وحيــث أن رجــوع املدعــى عليــه‬\n‫عــن هــذا االقــرار غيــر مقبــول وال يســقط التعزيــز وبنــاء علــى التقريــر‬\n‫الكيميائــي املذكــور آنفــا وبنــاء علــى املــواد (‪ )38‬و(‪ )56‬و( ‪ )60‬و(‪)62‬‬\n‫مــن نظــام مكافحــة املخــدرات ولقلــة الكميــة املروجــة وعــدم وجــود‬\n‫ســوابق علــى املدعــى عليــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بترويــج‬\n‫قطعــة مــن احلشــيش املخــدر عــن طريــق البيــع وحيــازة ثالثــن حبــة مــن‬\n\n\n                                                                                       ‫‪120‬‬\n\f      ‫احلبــوب احملظــورة وســيجارة مخلوطــة باحلشــيش املخــدر تــزن جرام ـ ًا‬\n      ‫واحــد بقصــد االســتعمال وحكمــت عليــه مبايلــي ‪ :‬اوال‪ :‬يســجن ســنتني‬\n      ‫تبــدأ مــن تاريــخ توقيفــه ويجلــد ثالثمائــة جلــدة مفرقــة علــى ســت مــرات‬\n      ‫متســاوية بــن املــرة واالخــرى خمســة عشــر يومــا ويدفــع غرامــة ماليــة‬\n      ‫ألــف ريــال ‪ ،‬ثانيــا ‪ :‬يجلــد ثمانــن جلــدة حــد املســكر لتعاطيــه احلشــيش‬\n      ‫املخــدر وبعــد عشــرة أيــام يجلــد الدفعــة االولــى مــن جلــد التعزيــز ‪ ،‬ثالثــا‬\n      ‫‪ :‬مينــع مــن الســفر الــى خــارج اململكــة مــدة ســنتني تبــدأ بعــد تنفيــذ‬\n      ‫عقوبــة الســجن ‪ ،‬رابعــا ‪ :‬مصــادرة جهــاز الهاتــف اجلــوال والشــريحة‬\n      ‫املســتخدمتني يف اجلرميــة وعقوبتــه لقــاء تســتره علــى مصــدر مــا ضبــط‬\n      ‫داخلــه فيمــا حكــم بــه أوال وبعــرض ذلــك علــى املدعــى عليــه قــرر عــدم‬\n      ‫القناعــة وقــرر املدعــي العــام طلــب رفــع القضيــة حملكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة فأفهمــت املدعــى عليــه بــأن عليــه تقــدمي الالئحــة‬\n      ‫االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ اســتالم نســخة احلكــم واال‬\n      ‫ســيتم رفــع القضيــة الــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪ 1433/09/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض ففــي يــوم األربعــاء املوافــق‪ 1434/01/28‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 45‬وفيهــا حضــر املدعــى عليــه وقــد عــادت إلينــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مبوجــب القــرار رقــم ‪33464791‬‬\n      ‫وتاريــخ ‪1433/11/24‬ه ـ وفيــه مانصــه وبدراســة القــرار وصــور ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة لوحــظ باألكثريــة مــا يلــي ‪-1‬‬\n      ‫املدعــى عليــه ادعــى انــه اعتــرف بســبب الضــرب الــذي تعــرض لــه يف‬\n\n\n‫‪121‬‬\n\f‫مكافحــة املخــدرات ولــم جنــد فضيلتــه طلــب بينه من املدعــى عليه على‬\n‫ذلــك ‪ -2‬لــم يثبــت فضيلتــه إدانــة املدعــى عليــه باســتعماله احلشــيش قبــل‬\n‫احلكــم عليــه أ‪.‬ه ـ فجــرى ســؤال املدعــى عليــه هــل لديــه بينــه علــى دعوى‬\n‫اإلكــراه وانــه تعــرض لضــرب قــال ليــس لــدي بينــه وثبــت لــدي إدانــة‬\n‫املدعــى عليــه باســتعمال احلشــيش املخــدر وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/28‬هـ‬\n‫احلمــد هلل وحــده‪ ...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ 34/3761‬وتاريــخ‬\n‫‪ 1434/2/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمة الشــيخ‪ ........./‬املســجل برقم ‪ ............‬وتاريخ ‪1433/9/12‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ....... /‬يف قضيــة مخــدرات املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــه ‪،‬وباإلطــاع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n‫علــى قرارنــا رقــم ‪ 33464791‬وتاريــخ ‪1433/11/24‬ه ـ قــررت الدائــرة‬\n‫باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪،‬واهلل املوفــق‬\n                     ‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪0‬‬\n\n\n\n\n                                                                                   ‫‪122‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":114,"source_page_end":122,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a695448d6aa94892dd73897d701062eb8120b6d8869ec30a246f7961826b20e7","normalized_text_hash":"ae48b93ba1d2d64b85f082be3fcae7535eee7761c0c8587b64616b56963a71ea","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p114-33409886"}]$archive_payload$::jsonb AS data)
